INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('KISW.G2.SARUFI.T10_VINYUME_VYA_VITENDO.a', 'KISW.G2.SARUFI.T10_VINYUME_VYA_VITENDO', 'a', 'kutambua vinyume vya vitendo katika sentensi mbalimbali', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
