INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'KISW.G2.KUSIKI.T1_MAAMKUZI_NA_MAAGANO', 'kiswahili', 2, 'Tumia maamkuzi na maagano yafaayo na majibu yake', ARRAY['KISW.G2.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.a', 'KISW.G2.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.b']::text[], 'Chooses the greeting or farewell that fits who is met (a friend, an elder, a group), the time of day and whether arriving or leaving, and gives the right reply (Hujambo? Sijambo; Shikamoo, Marahaba; Hamjambo? Hatujambo), in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua salamu ifaayo","chagua jibu la salamu","igiza salamu (mwalimu anasikiliza)"]'::jsonb, '["recall","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSOMA.T1_KUSOMA_UFAHAMU_KUSOM.UFAHAMU', 'KISW.G2.KUSOMA.T1_KUSOMA_UFAHAMU_KUSOM', 'kiswahili', 2, 'Soma kifungu chepesi: msamiati, ujumbe, kutabiri na mafunzo', ARRAY['KISW.G2.KUSOMA.T1_KUSOMA_UFAHAMU_KUSOM.a', 'KISW.G2.KUSOMA.T1_KUSOMA_UFAHAMU_KUSOM.b', 'KISW.G2.KUSOMA.T1_KUSOMA_UFAHAMU_KUSOM.c', 'KISW.G2.KUSOMA.T1_KUSOMA_UFAHAMU_KUSOM.d']::text[], 'Reads a short passage on shuleni, gives the meaning of a theme word from the sentence around it, says the message, predicts what happens next from the clues in the picture and says the lesson, answering from the passage and not from his own life, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maana ya neno","chagua ujumbe","tabiri kitakachotokea","chagua funzo"]'::jsonb, '["comprehension","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUANDI.T1_HATI_NADHIFU.HATI_NADHIFU', 'KISW.G2.KUANDI.T1_HATI_NADHIFU', 'kiswahili', 2, 'Andika kifungu kwa hati nadhifu', ARRAY['KISW.G2.KUANDI.T1_HATI_NADHIFU.a', 'KISW.G2.KUANDI.T1_HATI_NADHIFU.b']::text[], 'Writes a passage of about 15 words in neat handwriting: letters well formed and on the line, space between words, through the steps to a clean copy, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maandishi nadhifu","tambua kosa","andika kifungu (mwalimu anasahihisha)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.SARUFI.T1_MATUMIZI_YA_WEWE_NA_.NAFSI', 'KISW.G2.SARUFI.T1_MATUMIZI_YA_WEWE_NA_', 'kiswahili', 2, 'Tumia wewe na nyinyi ipasavyo katika sentensi', ARRAY['KISW.G2.SARUFI.T1_MATUMIZI_YA_WEWE_NA_.a', 'KISW.G2.SARUFI.T1_MATUMIZI_YA_WEWE_NA_.b']::text[], 'Uses wewe to speak to one person and nyinyi to many, with the matching subject marker (wewe u-, nyinyi m-), answers a wewe-question with mimi, and puts -ku- inside the verb for "you" as object (nitakupa), in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI', 'KISW.G2.KUSIKI.T2_MATAMSHI_BORA', 'kiswahili', 2, 'Tambua na utamke silabi za sauti /mw/, /nj/ katika maneno na sentensi', ARRAY['KISW.G2.KUSIKI.T2_MATAMSHI_BORA.a', 'KISW.G2.KUSIKI.T2_MATAMSHI_BORA.b', 'KISW.G2.KUSIKI.T2_MATAMSHI_BORA.c', 'KISW.G2.KUSIKI.T2_MATAMSHI_BORA.d']::text[], 'Hears and says the target sounds /mw/, /nj/ in syllables and words (mwalimu, njia, mwana), splits a word into its syllables, and picks or uses a word that carries the sound, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno lenye sauti","gawa neno kwa silabi","chagua matamshi sahihi","tamka neno (mwalimu anasikiliza)"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA', 'kiswahili', 2, 'Soma kifungu chepesi chenye sauti /mw/, /nj/ kwa matamshi bora, sauti inayosikika, kasi ifaayo na ishara', ARRAY['KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA.a', 'KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA.b', 'KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA.c', 'KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA.d', 'KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA.e']::text[], 'Finds the target sounds /mw/, /nj/ in a short story, reads it aloud with every sound clear, loud enough for the class, at about 33 words a minute, pausing at the koma and kikomo and raising the voice for a question; in the app picks the better reading of a line, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua sauti lengwa","chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'KISW.G2.KUANDI.T2_HATI_NADHIFU_HERUFI_', 'kiswahili', 2, 'Andika kwa hati nadhifu ukitumia herufi kubwa ifaavyo', ARRAY['KISW.G2.KUANDI.T2_HATI_NADHIFU_HERUFI_.a', 'KISW.G2.KUANDI.T2_HATI_NADHIFU_HERUFI_.b']::text[], 'Writes a passage of about 15 words in neat handwriting: letters well formed and on the line, capitals only at the start of a sentence or name, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maandishi nadhifu","tambua kosa","andika kifungu (mwalimu anasahihisha)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.SARUFI.T2_UMOJA_NA_WINGI_WA_VI.UMOJA_WINGI', 'KISW.G2.SARUFI.T2_UMOJA_NA_WINGI_WA_VI', 'kiswahili', 2, 'Badilisha vifungu vya maneno mawili kutoka umoja hadi wingi', ARRAY['KISW.G2.SARUFI.T2_UMOJA_NA_WINGI_WA_VI.a', 'KISW.G2.SARUFI.T2_UMOJA_NA_WINGI_WA_VI.b']::text[], 'Turns a two-word group from singular to plural and back (chakula changu - vyakula vyetu, kitanda changu - vitanda vyetu), changing the noun by its ngeli and the word that goes with it, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA', 'KISW.G2.KUSIKI.T3_MANENO_YA_HESHIMA_NA', 'kiswahili', 2, 'Tumia maneno ya heshima na adabu: tafadhali, asante, samahani, pole, karibu', ARRAY['KISW.G2.KUSIKI.T3_MANENO_YA_HESHIMA_NA.a', 'KISW.G2.KUSIKI.T3_MANENO_YA_HESHIMA_NA.b']::text[], 'Picks and uses the polite word that fits the situation (tafadhali or naomba to ask, asante to thank, karibu to answer asante, samahani to apologise, pole to sympathise) and addresses an adult with a title, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno la adabu","kamilisha mazungumzo","igiza hali (mwalimu anasikiliza)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSOMA.T3_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'KISW.G2.KUSOMA.T3_KUSOMA_KWA_UFAHAMU_K', 'kiswahili', 2, 'Soma kifungu chepesi: msamiati, ujumbe, kutabiri na mafunzo', ARRAY['KISW.G2.KUSOMA.T3_KUSOMA_KWA_UFAHAMU_K.a', 'KISW.G2.KUSOMA.T3_KUSOMA_KWA_UFAHAMU_K.b', 'KISW.G2.KUSOMA.T3_KUSOMA_KWA_UFAHAMU_K.c', 'KISW.G2.KUSOMA.T3_KUSOMA_KWA_UFAHAMU_K.d']::text[], 'Reads a short passage on lishe bora, gives the meaning of a theme word from the sentence around it, says the message, predicts what happens next from the clues in the picture and says the lesson, answering from the passage and not from his own life, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maana ya neno","chagua ujumbe","tabiri kitakachotokea","chagua funzo"]'::jsonb, '["comprehension","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUANDI.T3_MPANGILIO_WA_HERUFI_.HATI_NADHIFU', 'KISW.G2.KUANDI.T3_MPANGILIO_WA_HERUFI_', 'kiswahili', 2, 'Andika kwa hati nadhifu ukitumia herufi ndogo ifaavyo', ARRAY['KISW.G2.KUANDI.T3_MPANGILIO_WA_HERUFI_.a', 'KISW.G2.KUANDI.T3_MPANGILIO_WA_HERUFI_.b']::text[], 'Writes a passage of about 20 words in neat handwriting: letters well formed and on the line, small letters of the right height, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maandishi nadhifu","tambua kosa","andika kifungu (mwalimu anasahihisha)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.SARUFI.T3_MATUMIZI_YA_HUYO_NA_.VIONYESHI', 'KISW.G2.SARUFI.T3_MATUMIZI_YA_HUYO_NA_', 'kiswahili', 2, 'Tumia huyo na hao ipasavyo katika sentensi', ARRAY['KISW.G2.SARUFI.T3_MATUMIZI_YA_HUYO_NA_.a', 'KISW.G2.SARUFI.T3_MATUMIZI_YA_HUYO_NA_.b']::text[], 'Uses huyo for one person near the listener and hao for many, tells them from huyu/hawa (near the speaker), and uses hicho/hivyo, not huyo, for ki-vi things, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'KISW.G2.KUSIKI.T4_MATAMSHI_BORA_SAUTI_', 'kiswahili', 2, 'Tambua na utamke silabi za sauti /ch/, /dh/ katika maneno na sentensi', ARRAY['KISW.G2.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.a', 'KISW.G2.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.b', 'KISW.G2.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.c']::text[], 'Hears and says the target sounds /ch/, /dh/ in syllables and words (chombo, dhoruba, chai), splits a word into its syllables, and picks or uses a word that carries the sound, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno lenye sauti","gawa neno kwa silabi","chagua matamshi sahihi","tamka neno (mwalimu anasikiliza)"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S', 'kiswahili', 2, 'Soma kifungu chepesi chenye sauti /ch/, /dh/ kwa matamshi bora, sauti inayosikika, kasi ifaayo na ishara', ARRAY['KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.a', 'KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.b', 'KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.c', 'KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.d', 'KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.e']::text[], 'Finds the target sounds /ch/, /dh/ in a short story, reads it aloud with every sound clear, loud enough for the class, at about 36 words a minute, pausing at the koma and kikomo and raising the voice for a question; in the app picks the better reading of a line, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua sauti lengwa","chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUANDI.T4_NAFASI_KATIKA_MAANDI.NAFASI_KATI_YA_MANENO', 'KISW.G2.KUANDI.T4_NAFASI_KATIKA_MAANDI', 'kiswahili', 2, 'Andika sentensi ukiacha nafasi ifaayo kati ya maneno', ARRAY['KISW.G2.KUANDI.T4_NAFASI_KATIKA_MAANDI.a', 'KISW.G2.KUANDI.T4_NAFASI_KATIKA_MAANDI.b']::text[], 'Writes sentences with one finger space between words, none inside a word, keeps the verb and its parts as one word (ninakwenda, not ni na kwenda) and does not run on into the next sentence, in 8 of 10 new items (the teacher also checks it in the exercise book).', '["chagua sentensi iliyoandikwa vizuri","hesabu maneno","andika sentensi (mwalimu anasahihisha)"]'::jsonb, '["application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.SARUFI.T4_UMOJA_NA_WINGI.UMOJA_WINGI', 'KISW.G2.SARUFI.T4_UMOJA_NA_WINGI', 'kiswahili', 2, 'Soma na uandike vifungu vya maneno ya usafiri katika umoja na wingi', ARRAY['KISW.G2.SARUFI.T4_UMOJA_NA_WINGI.a', 'KISW.G2.SARUFI.T4_UMOJA_NA_WINGI.b', 'KISW.G2.SARUFI.T4_UMOJA_NA_WINGI.c']::text[], 'Reads and writes word groups about transport in singular and plural: li-ma nouns take ma- (basi - mabasi, gari - magari), people take wa- (mwendeshaji - waendeshaji), n-n nouns stay the same (ndege - ndege) and the describing word agrees, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'KISW.G2.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ', 'kiswahili', 2, 'Sikiliza kifungu, eleza ujumbe na msamiati wake, na usimulie upya', ARRAY['KISW.G2.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.a', 'KISW.G2.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.b', 'KISW.G2.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.c', 'KISW.G2.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.d']::text[], 'After hearing a short passage (Sungura mjanja alimdanganya fisi akaokoa chakula chake), says its message, gives the meaning of a new word from it, uses the word in a sentence of his own and retells the events in order, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua ujumbe","chagua maana ya neno","panga matukio","simulia upya (mwalimu anasikiliza)"]'::jsonb, '["comprehension","sequencing"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'KISW.G2.KUSOMA.T5_KUSOMA_KWA_UFAHAMU', 'kiswahili', 2, 'Soma kifungu chepesi: msamiati, ujumbe, kutabiri na mafunzo', ARRAY['KISW.G2.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.a', 'KISW.G2.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.b', 'KISW.G2.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.c', 'KISW.G2.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.d']::text[], 'Reads a short passage on mnyama nimpendaye, gives the meaning of a theme word from the sentence around it, says the message, predicts what happens next from the clues in the picture and says the lesson, answering from the passage and not from his own life, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maana ya neno","chagua ujumbe","tabiri kitakachotokea","chagua funzo"]'::jsonb, '["comprehension","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUANDI.T5_UAKIFISHI.ALAMA', 'KISW.G2.KUANDI.T5_UAKIFISHI', 'kiswahili', 2, 'Tumia alama ya kiulizi ipasavyo katika maandishi', ARRAY['KISW.G2.KUANDI.T5_UAKIFISHI.a', 'KISW.G2.KUANDI.T5_UAKIFISHI.b', 'KISW.G2.KUANDI.T5_UAKIFISHI.c']::text[], 'Tells a question from a statement, ends each with its mark (? or .), starts the next sentence with a capital, and writes a passage of about 20 words with the marks in place, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["weka alama sahihi","chagua sentensi iliyoakifishwa vizuri","andika kifungu (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.SARUFI.T5_MATUMIZI_YA_AKO_NA_E.VIMILIKISHI', 'KISW.G2.SARUFI.T5_MATUMIZI_YA_AKO_NA_E', 'kiswahili', 2, 'Tumia -ako na -enu ipasavyo katika sentensi', ARRAY['KISW.G2.SARUFI.T5_MATUMIZI_YA_AKO_NA_E.a', 'KISW.G2.SARUFI.T5_MATUMIZI_YA_AKO_NA_E.b']::text[], 'Uses -ako for something owned by one person spoken to and -enu for many, with the prefix of the thing owned (mbwa wako, vikombe vyako, madaftari yenu), placed after the noun, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'KISW.G2.KUSIKI.T6_MATAMSHI_BORA', 'kiswahili', 2, 'Tambua na utamke silabi za sauti /ny/, /ng/ katika maneno na sentensi', ARRAY['KISW.G2.KUSIKI.T6_MATAMSHI_BORA.a', 'KISW.G2.KUSIKI.T6_MATAMSHI_BORA.b']::text[], 'Hears and says the target sounds /ny/, /ng/ in syllables and words (nyanya, ngoma, nyama), splits a word into its syllables, and picks or uses a word that carries the sound, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno lenye sauti","gawa neno kwa silabi","chagua matamshi sahihi","tamka neno (mwalimu anasikiliza)"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA', 'kiswahili', 2, 'Soma kifungu chepesi chenye sauti /ny/, /ng/ kwa matamshi bora, sauti inayosikika, kasi ifaayo na ishara', ARRAY['KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA.a', 'KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA.b', 'KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA.c', 'KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA.d', 'KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA.e']::text[], 'Finds the target sounds /ny/, /ng/ in a short story, reads it aloud with every sound clear, loud enough for the class, at about 39 words a minute, pausing at the koma and kikomo and raising the voice for a question; in the app picks the better reading of a line, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua sauti lengwa","chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUANDI.T6_TAHAJIA_IMLA.IMLA', 'KISW.G2.KUANDI.T6_TAHAJIA_IMLA', 'kiswahili', 2, 'Andika maneno yanayotamkwa kwenye imla kwa tahajia sahihi', ARRAY['KISW.G2.KUANDI.T6_TAHAJIA_IMLA.a', 'KISW.G2.KUANDI.T6_TAHAJIA_IMLA.b', 'KISW.G2.KUANDI.T6_TAHAJIA_IMLA.c']::text[], 'Writes the words the teacher reads (about 10 words) with the right letters: the Kiswahili sound and not the home sound, the nasal kept (nd, mb, ng), long vowels doubled and ng'' with its apostrophe, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua tahajia sahihi","sahihisha neno","imla (mwalimu anasoma)"]'::jsonb, '["recall","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.SARUFI.T6_MATUMIZI_YA_REFU_KUB.VIVUMISHI', 'KISW.G2.SARUFI.T6_MATUMIZI_YA_REFU_KUB', 'kiswahili', 2, 'Tumia -refu, -kubwa na -tamu ipasavyo katika sentensi', ARRAY['KISW.G2.SARUFI.T6_MATUMIZI_YA_REFU_KUB.a', 'KISW.G2.SARUFI.T6_MATUMIZI_YA_REFU_KUB.b']::text[], 'Uses -refu, -kubwa and -tamu after the noun with the right prefix (babu mrefu, kiti kikubwa, nyumba ndefu, wajomba warefu) and picks the right member of a pair (mrefu or mfupi), in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSIKI.T7_MAAGIZO.MAAGIZO', 'KISW.G2.KUSIKI.T7_MAAGIZO', 'kiswahili', 2, 'Fuata na utoe maagizo mepesi kwa usahihi', ARRAY['KISW.G2.KUSIKI.T7_MAAGIZO.a', 'KISW.G2.KUSIKI.T7_MAAGIZO.b']::text[], 'Follows a one- or two-step instruction in the right order, reads the direction and action words in it (simama, keti, kulia, kushoto, juu, chini), and gives a clear, polite instruction that names what to do and to what, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua kitendo sahihi","panga hatua","toa agizo (mwalimu anasikiliza)"]'::jsonb, '["comprehension","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSOMA.T7_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'KISW.G2.KUSOMA.T7_KUSOMA_KWA_UFAHAMU_K', 'kiswahili', 2, 'Soma kifungu chepesi: msamiati, ujumbe, kutabiri na mafunzo', ARRAY['KISW.G2.KUSOMA.T7_KUSOMA_KWA_UFAHAMU_K.a', 'KISW.G2.KUSOMA.T7_KUSOMA_KWA_UFAHAMU_K.b', 'KISW.G2.KUSOMA.T7_KUSOMA_KWA_UFAHAMU_K.c', 'KISW.G2.KUSOMA.T7_KUSOMA_KWA_UFAHAMU_K.d']::text[], 'Reads a short passage on sebuleni, gives the meaning of a theme word from the sentence around it, says the message, predicts what happens next from the clues in the picture and says the lesson, answering from the passage and not from his own life, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maana ya neno","chagua ujumbe","tabiri kitakachotokea","chagua funzo"]'::jsonb, '["comprehension","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUANDI.T7_UHARIRI.UHARIRI', 'KISW.G2.KUANDI.T7_UHARIRI', 'kiswahili', 2, 'Hariri maandishi yako: herufi kubwa, kikomo, maneno na tahajia', ARRAY['KISW.G2.KUANDI.T7_UHARIRI.a', 'KISW.G2.KUANDI.T7_UHARIRI.b']::text[], 'Reads his own writing back and corrects it: a capital at the start, a kikomo or kiulizi at the end, no word left out, words spelt right, then makes a clean copy, in 8 of 10 new items (the teacher also checks the before and after copies).', '["tambua kosa","sahihisha sentensi","hariri kifungu (mwalimu anasahihisha)"]'::jsonb, '["evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.SARUFI.T7_UKANUSHO_WA_NAFSI_YA.UKANUSHAJI', 'KISW.G2.SARUFI.T7_UKANUSHO_WA_NAFSI_YA', 'kiswahili', 2, 'Kanusha sentensi za nafsi ya pili umoja na wingi', ARRAY['KISW.G2.SARUFI.T7_UKANUSHO_WA_NAFSI_YA.a', 'KISW.G2.SARUFI.T7_UKANUSHO_WA_NAFSI_YA.b']::text[], 'Makes the negative of a present-tense sentence in the second person: wewe unasoma - wewe husomi, nyinyi mnasoma - nyinyi hamsomi (hu-/ham-, no -na-, final -a to -i), in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'KISW.G2.KUSIKI.T8_MATAMSHI_BORA', 'kiswahili', 2, 'Tambua na utamke silabi za sauti /gh/, /ng''/ katika maneno na sentensi', ARRAY['KISW.G2.KUSIKI.T8_MATAMSHI_BORA.a', 'KISW.G2.KUSIKI.T8_MATAMSHI_BORA.b']::text[], 'Hears and says the target sounds /gh/, /ng''/ in syllables and words (ghafla, ng''ombe, ghala), splits a word into its syllables, and picks or uses a word that carries the sound, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno lenye sauti","gawa neno kwa silabi","chagua matamshi sahihi","tamka neno (mwalimu anasikiliza)"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA', 'kiswahili', 2, 'Soma kifungu chepesi chenye sauti /gh/, /ng''/ kwa matamshi bora, sauti inayosikika, kasi ifaayo na ishara', ARRAY['KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA.a', 'KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA.b', 'KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA.c', 'KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA.d', 'KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA.e']::text[], 'Finds the target sounds /gh/, /ng''/ in a short story, reads it aloud with every sound clear, loud enough for the class, at about 42 words a minute, pausing at the koma and kikomo and raising the voice for a question; in the app picks the better reading of a line, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua sauti lengwa","chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUANDI.T8_TAHAJIA.TAHAJIA', 'KISW.G2.KUANDI.T8_TAHAJIA', 'kiswahili', 2, 'Andika insha fupi kwa tahajia sahihi za maneno', ARRAY['KISW.G2.KUANDI.T8_TAHAJIA.a', 'KISW.G2.KUANDI.T8_TAHAJIA.b']::text[], 'Writes the words of his own writing (about 20 words) with the right letters: the Kiswahili sound and not the home sound, the nasal kept (nd, mb, ng), long vowels doubled and ng'' with its apostrophe, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua tahajia sahihi","sahihisha neno","andika (mwalimu anasahihisha)"]'::jsonb, '["recall","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.SARUFI.T8_MATUMIZI_YA_HUU_NA_H.VIONYESHI', 'KISW.G2.SARUFI.T8_MATUMIZI_YA_HUU_NA_H', 'kiswahili', 2, 'Tumia huu na hii kutaja vitu vilivyo karibu', ARRAY['KISW.G2.SARUFI.T8_MATUMIZI_YA_HUU_NA_H.a', 'KISW.G2.SARUFI.T8_MATUMIZI_YA_HUU_NA_H.a_2', 'KISW.G2.SARUFI.T8_MATUMIZI_YA_HUU_NA_H.b']::text[], 'Uses huu with a near m-mi noun in the singular and hii in the plural (mti huu - miti hii, mlango huu - milango hii), and ule for one far away, not huyu or hii for everything, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSIKI.T9_MAZUNGUMZO_YA_PAPO_K.MAZUNGUMZO', 'KISW.G2.KUSIKI.T9_MAZUNGUMZO_YA_PAPO_K', 'kiswahili', 2, 'Shiriki mazungumzo kuhusu kumtembelea daktari kwa zamu, kwa matamshi bora na ishara zifaazo', ARRAY['KISW.G2.KUSIKI.T9_MAZUNGUMZO_YA_PAPO_K.a', 'KISW.G2.KUSIKI.T9_MAZUNGUMZO_YA_PAPO_K.b', 'KISW.G2.KUSIKI.T9_MAZUNGUMZO_YA_PAPO_K.c']::text[], 'Takes part in a short conversation about kumtembelea daktari: keeps to the topic, waits for his turn, speaks Kiswahili without English or Sheng words, says sounds clearly and uses gestures that match the words, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua jibu linalofaa mada","tambua kosa la mazungumzo","zungumza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'KISW.G2.KUSOMA.T9_KUSOMA_KWA_UFAHAMU', 'kiswahili', 2, 'Soma kifungu chepesi: msamiati, ujumbe, kutabiri na mafunzo', ARRAY['KISW.G2.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.a', 'KISW.G2.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.b', 'KISW.G2.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.c', 'KISW.G2.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.d']::text[], 'Reads a short passage on hospitalini, gives the meaning of a theme word from the sentence around it, says the message, predicts what happens next from the clues in the picture and says the lesson, answering from the passage and not from his own life, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua maana ya neno","chagua ujumbe","tabiri kitakachotokea","chagua funzo"]'::jsonb, '["comprehension","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUANDI.T9_KUANDIKA_KIFUNGU.KIFUNGU', 'KISW.G2.KUANDI.T9_KUANDIKA_KIFUNGU', 'kiswahili', 2, 'Andika kifungu kifupi kutokana na picha', ARRAY['KISW.G2.KUANDI.T9_KUANDIKA_KIFUNGU.a', 'KISW.G2.KUANDI.T9_KUANDIKA_KIFUNGU.b']::text[], 'Writes a short paragraph about a picture on hospitalini: a title that fits, sentences in order, one tense, Kiswahili words only, capitals and kikomo in place, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua kichwa kifaacho","panga sentensi","tambua kosa","andika (mwalimu anasahihisha)"]'::jsonb, '["application","sequencing"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.SARUFI.T9_MATUMIZI_YA_VIZURI_N.VIELEZI', 'KISW.G2.SARUFI.T9_MATUMIZI_YA_VIZURI_N', 'kiswahili', 2, 'Tumia vizuri, vibaya, polepole na haraka katika sentensi', ARRAY['KISW.G2.SARUFI.T9_MATUMIZI_YA_VIZURI_N.a', 'KISW.G2.SARUFI.T9_MATUMIZI_YA_VIZURI_N.b']::text[], 'Says how an action is done with vizuri, vibaya, polepole and haraka after the verb (anatembea polepole), tells them from describing words for things (chakula kizuri), and picks the right word of a pair, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'KISW.G2.KUSIKI.T10_MATAMSHI_BORA', 'kiswahili', 2, 'Tambua na utamke silabi za sauti /r/, /l/ katika maneno na sentensi', ARRAY['KISW.G2.KUSIKI.T10_MATAMSHI_BORA.a', 'KISW.G2.KUSIKI.T10_MATAMSHI_BORA.b']::text[], 'Hears and says the target sounds /r/, /l/ in syllables and words (radi, baridi, leo), splits a word into its syllables, and picks or uses a word that carries the sound, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno lenye sauti","gawa neno kwa silabi","chagua matamshi sahihi","tamka neno (mwalimu anasikiliza)"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA', 'kiswahili', 2, 'Soma kifungu chepesi chenye sauti /r/, /l/ kwa matamshi bora, sauti inayosikika, kasi ifaayo na ishara', ARRAY['KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA.a', 'KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA.b', 'KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA.c', 'KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA.d', 'KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA.e']::text[], 'Finds the target sounds /r/, /l/ in a short story, reads it aloud with every sound clear, loud enough for the class, at about 45 words a minute, pausing at the koma and kikomo and raising the voice for a question; in the app picks the better reading of a line, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["tambua sauti lengwa","chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI.TAHAJIA', 'KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI', 'kiswahili', 2, 'Andika maneno kwa tahajia sahihi', ARRAY['KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI.a', 'KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI.b', 'KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI.c']::text[], 'Writes the words of his own writing (about 20 words) with the right letters: the Kiswahili sound and not the home sound, the nasal kept (nd, mb, ng), long vowels doubled and ng'' with its apostrophe, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua tahajia sahihi","sahihisha neno","andika (mwalimu anasahihisha)"]'::jsonb, '["recall","application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G2.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'KISW.G2.SARUFI.T10_VINYUME_VYA_VITENDO', 'kiswahili', 2, 'Tambua na utumie vinyume vya vitendo katika sentensi', ARRAY['KISW.G2.SARUFI.T10_VINYUME_VYA_VITENDO.a', 'KISW.G2.SARUFI.T10_VINYUME_VYA_VITENDO.b']::text[], 'Gives and uses the opposite action of a verb (fungua - funga, panda - shuka, anza - maliza, keti - simama), not its negative, a word of the same meaning, or a place word, in 8 of 10 new items (the teacher also hears it in class, with the KICD rubric).', '["chagua neno sahihi","jaza pengo","sahihisha sentensi","tunga sentensi (mwalimu anasahihisha)"]'::jsonb, '["application","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
