INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI.TAHAJIA', 'KISW.G2.KUANDI.T8_TAHAJIA.TAHAJIA', 'skill', 'essential', 'Spelling in his own sentences (Theme 8) comes first.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI.TAHAJIA', 'KISW.G2.KUANDI.T4_NAFASI_KATIKA_MAANDI.NAFASI_KATI_YA_MANENO', 'skill', 'essential', 'Space between words in a sentence.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G2.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'KISW.G1.SARUFI.T10_VINYUME_VYA_VITENDO.b', 'outcome', 'essential', 'Opposite actions of Grade 1 come first.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('KISW.G2.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'KISW.G2.SARUFI.T7_UKANUSHO_WA_NAFSI_YA.UKANUSHAJI', 'skill', 'helpful', 'Knowing the negative lets the child tell it from the opposite.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M2_SAL_REPLY_T1', 'KISW.G2.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Answers a greeting with the same greeting (Hujambo? Hujambo!) instead of its reply.', '{"question":"Rafiki anakusalimu: \"Hujambo?\" Unajibu nini?","wrong_answer":"Hujambo","correct_answer":"Sijambo"}'::jsonb, 'The child hears the greeting as a sound to echo, as with "Hello" in English; the question-and-answer pair has not been learnt.', 'The question "Rafiki anakusalimu: "Hujambo?" Unajibu nini?" with "Hujambo" among the options.', 'Act it as a ball game: the greeting is thrown, the reply is caught; the two words are on two different cards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M2_SAL_ELDER_T1', 'KISW.G2.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Greets an elder with a peer or Sheng greeting (Mambo! Sasa!) instead of Shikamoo.', '{"question":"Unamwona babu njiani. Unamsalimu vipi?","wrong_answer":"Mambo babu!","correct_answer":"Shikamoo babu!"}'::jsonb, 'Mambo and Sasa are what the child hears most among children and on the street; he has not been taught that an elder is greeted differently.', 'The question "Unamwona babu njiani. Unamsalimu vipi?" with "Mambo babu!" among the options.', 'Sort picture cards of people (babu, rafiki, mwalimu) into two piles: Shikamoo and Hujambo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M2_SAL_MARAHABA_T1', 'KISW.G2.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Gives the elder''s reply to the child''s greeting the wrong way round (the elder says Shikamoo, or the child says Marahaba).', '{"question":"Mtoto anamsalimu bibi: \"Shikamoo bibi!\" Bibi anajibu nini?","wrong_answer":"Shikamoo","correct_answer":"Marahaba"}'::jsonb, 'Both words are heard together and the child does not yet know which belongs to the young person and which to the elder.', 'The question "Mtoto anamsalimu bibi: "Shikamoo bibi!" Bibi anajibu nini?" with "Shikamoo" among the options.', 'Role-play with a hat for the elder: only the one with the hat may say Marahaba.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M2_SAL_TIME_T1', 'KISW.G2.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Uses the greeting of another time of day.', '{"question":"Mnakutana na mwalimu mchana baada ya chakula. Unamsalimu vipi?","wrong_answer":"Habari za asubuhi mwalimu!","correct_answer":"Habari za mchana mwalimu!"}'::jsonb, 'The child learnt one greeting as a set phrase and uses it at every hour.', 'The question "Mnakutana na mwalimu mchana baada ya chakula. Unamsalimu vipi?" with "Habari za asubuhi mwalimu!" among the options.', 'A clock or sun chart: asubuhi, mchana, jioni, usiku; the child moves the arrow and says the greeting for that time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M2_SAL_LEAVE_T1', 'KISW.G2.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Uses a greeting when leaving, or a farewell when arriving.', '{"question":"Unaondoka shuleni jioni. Unamuaga mwalimu vipi?","wrong_answer":"Hujambo mwalimu!","correct_answer":"Kwaheri mwalimu, tutaonana kesho!"}'::jsonb, 'Greeting and farewell words are learnt on one chart and the child mixes the two columns.', 'The question "Unaondoka shuleni jioni. Unamuaga mwalimu vipi?" with "Hujambo mwalimu!" among the options.', 'Act out a door: walk in and greet, walk out and say goodbye.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI.M2_SAL_GROUP_T1', 'KISW.G2.KUSIKI.T1_MAAMKUZI_NA_MAAGANO.MAAMKUZI', 'Greets a group with the singular greeting (Hujambo?) or answers for a group with Sijambo.', '{"question":"Mwalimu anaingia darasani na kusema: \"Hamjambo wanafunzi?\" Darasa linajibu nini?","wrong_answer":"Sijambo","correct_answer":"Hatujambo"}'::jsonb, 'The child knows one pair only; the plural forms hamjambo/hatujambo follow the person marker (m-, tu-), which has not been noticed.', 'The question "Mwalimu anaingia darasani na kusema: "Hamjambo wanafunzi?" Darasa linajibu nini?" with "Sijambo" among the options.', 'Greet one child, then the whole row; show that the word changes with one or many.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T1_KUSOMA_UFAHAMU_KUSOM.UFAHAMU.M2_UFM_WORD_T1', 'KISW.G2.KUSOMA.T1_KUSOMA_UFAHAMU_KUSOM.UFAHAMU', 'Gives "kukaribisha" the meaning of a word that looks or sounds like it.', '{"question":"Soma: \"Leo ni siku ya kwanza ya Neema shuleni. Mwalimu alimkaribisha darasani kwa tabasamu. Neema alipata rafiki mpya anayeitwa Amani.\" Neno \"kukaribisha\" lina maana gani?","wrong_answer":"kukasirisha","correct_answer":"kumpokea mtu kwa furaha"}'::jsonb, 'The child matches the word to a known one by its look instead of reading the sentence around it.', 'The question "Soma: "Leo ni siku ya kwanza ya Neema shuleni. Mwalimu alimkaribisha darasani kwa tabasamu. Neema alipata rafiki mpya anayeitwa Amani." Neno "kukaribisha" lina maana gani?" with "kukasirisha" among the options.', 'Cover the word; the child says what word would fit the sentence, then uncovers it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T1_KUSOMA_UFAHAMU_KUSOM.UFAHAMU.M2_UFM_MSG_T1', 'KISW.G2.KUSOMA.T1_KUSOMA_UFAHAMU_KUSOM.UFAHAMU', 'Gives one detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ni upi?","wrong_answer":"Neema alipata rafiki.","correct_answer":"Shule ni mahali pazuri pa kupata marafiki na kujifunza."}'::jsonb, 'The detail is what the child remembers best; he has not been asked what the writer wants us to know.', 'The question "Ujumbe wa kifungu ni upi?" with "Neema alipata rafiki." among the options.', 'Ask two questions side by side: "Nini kilitokea?" and "Kifungu kinatuambia nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T1_KUSOMA_UFAHAMU_KUSOM.UFAHAMU.M2_UFM_GUESS_T1', 'KISW.G2.KUSOMA.T1_KUSOMA_UFAHAMU_KUSOM.UFAHAMU', 'Predicts something the passage gives no clue for, without looking at the picture.', '{"question":"Picha inaonyesha kengele ikilia na watoto wakitoka nje. Nini kitatokea?","wrong_answer":"Watalala darasani.","correct_answer":"Wataenda kucheza wakati wa mapumziko."}'::jsonb, 'Prediction is taken as free imagination; the child has not been shown that clues in the text and picture point the way.', 'The question "Picha inaonyesha kengele ikilia na watoto wakitoka nje. Nini kitatokea?" with "Watalala darasani." among the options.', 'Underline the clue words and point at the picture; the guess must fit them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T1_KUSOMA_UFAHAMU_KUSOM.UFAHAMU.M2_UFM_LESSON_T1', 'KISW.G2.KUSOMA.T1_KUSOMA_UFAHAMU_KUSOM.UFAHAMU', 'Retells what happened when asked for the lesson.', '{"question":"Tunajifunza nini kutokana na kifungu?","wrong_answer":"Mwalimu alitabasamu.","correct_answer":"Tunapaswa kuwakaribisha wanafunzi wapya kwa upendo."}'::jsonb, 'The lesson question sounds like a what-happened question to the child.', 'The question "Tunajifunza nini kutokana na kifungu?" with "Mwalimu alitabasamu." among the options.', 'Start the answer with "Tunajifunza kwamba tunapaswa..."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T1_KUSOMA_UFAHAMU_KUSOM.UFAHAMU.M2_UFM_OWN_T1', 'KISW.G2.KUSOMA.T1_KUSOMA_UFAHAMU_KUSOM.UFAHAMU', 'Answers from his own life instead of from the passage.', '{"question":"Rafiki mpya wa Neema anaitwa nani?","wrong_answer":"Rafiki yangu anaitwa Juma.","correct_answer":"Amani"}'::jsonb, 'The child links the question to what he knows from home and does not check the text.', 'The question "Rafiki mpya wa Neema anaitwa nani?" with "Rafiki yangu anaitwa Juma." among the options.', 'Ask the child to point at the line in the passage that gives the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T1_HATI_NADHIFU.HATI_NADHIFU.M2_HAT_DRAFT_T1', 'KISW.G2.KUANDI.T1_HATI_NADHIFU.HATI_NADHIFU', 'Hands in the first draft with crossings and does not make a clean copy.', '{"question":"Ni hatua gani ya mwisho ya kuandika kifungu?","wrong_answer":"nakala ya kwanza","correct_answer":"nakala safi"}'::jsonb, 'The child thinks writing ends when the words are down; the steps maandalizi, nakala ya kwanza, urekebishaji, nakala safi are new.', 'The question "Ni hatua gani ya mwisho ya kuandika kifungu?" with "nakala ya kwanza" among the options.', 'Show the four steps as four boxes; the child ticks each one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T1_HATI_NADHIFU.HATI_NADHIFU.M2_HAT_COPY_T1', 'KISW.G2.KUANDI.T1_HATI_NADHIFU.HATI_NADHIFU', 'Leaves out words or a whole line when copying.', '{"question":"Nakili: \"Shule yetu ni safi.\"","wrong_answer":"Shule ni safi.","correct_answer":"Shule yetu ni safi."}'::jsonb, 'The child copies letter by letter and loses his place when looking back.', 'The question "Nakili: "Shule yetu ni safi."" with "Shule ni safi." among the options.', 'Copy phrase by phrase, moving a finger along the line; read the copy back against the original.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T1_HATI_NADHIFU.HATI_NADHIFU.M2_HAT_SPACE_T1', 'KISW.G2.KUANDI.T1_HATI_NADHIFU.HATI_NADHIFU', 'Leaves no space between words (Mamaanapika).', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"Mamaanapikachakula.","correct_answer":"Mama anapika chakula."}'::jsonb, 'Spoken Kiswahili runs words together; the child writes the stream as he hears it.', 'The question "Ni lipi limeandikwa vizuri?" with "Mamaanapikachakula." among the options.', 'Put a finger space after every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T1_HATI_NADHIFU.HATI_NADHIFU.M2_HAT_TURN_T1', 'KISW.G2.KUANDI.T1_HATI_NADHIFU.HATI_NADHIFU', 'Turns b and d (or p and q) round: dada written "baba" or "bada".', '{"question":"Andika neno \"dada\".","wrong_answer":"bada","correct_answer":"dada"}'::jsonb, 'Mirror letters are common in early writing; the child has not fixed the direction.', 'The question "Andika neno "dada"." with "bada" among the options.', 'Teach d as "c then a tall line"; trace it in sand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T1_HATI_NADHIFU.HATI_NADHIFU.M2_HAT_LINE_T1', 'KISW.G2.KUANDI.T1_HATI_NADHIFU.HATI_NADHIFU', 'Writes letters floating above the line or of mixed sizes, so the line goes up and down.', '{"question":"Maandishi nadhifu yanakaa wapi?","wrong_answer":"popote kwenye ukurasa","correct_answer":"juu ya mstari, herufi zikiwa na ukubwa sawa"}'::jsonb, 'The child writes fast and does not look at the line.', 'The question "Maandishi nadhifu yanakaa wapi?" with "popote kwenye ukurasa" among the options.', 'Trace the line with a finger first; every letter sits on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T1_MATUMIZI_YA_WEWE_NA_.NAFSI.M2_SAR_PREFIX_T1', 'KISW.G2.SARUFI.T1_MATUMIZI_YA_WEWE_NA_.NAFSI', 'The pronoun and the subject marker on the verb do not agree (Wao anacheza).', '{"question":"Jaza: Nyinyi ___ (soma) vizuri.","wrong_answer":"unasoma","correct_answer":"mnasoma"}'::jsonb, 'The child learns the pronoun as a word and the verb as a fixed form; he has not seen that the verb changes with the person.', 'The question "Jaza: Nyinyi ___ (soma) vizuri." with "unasoma" among the options.', 'Colour the pronoun and the verb''s first syllable the same colour: yeye a-, wao wa-, mimi ni-, sisi tu-, wewe u-, nyinyi m-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T1_MATUMIZI_YA_WEWE_NA_.NAFSI.M2_SAR_NUMBER_T1', 'KISW.G2.SARUFI.T1_MATUMIZI_YA_WEWE_NA_.NAFSI', 'Uses the one-person pronoun for many people, or the reverse.', '{"question":"Mwalimu anaongea na darasa zima: \"___ mnafanya kazi nzuri.\"","wrong_answer":"Wewe","correct_answer":"Nyinyi"}'::jsonb, 'The child has not linked the pronoun pair to one and many.', 'The question "Mwalimu anaongea na darasa zima: "___ mnafanya kazi nzuri."" with "Wewe" among the options.', 'Point at one child, then at a group, saying the right pronoun each time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T1_MATUMIZI_YA_WEWE_NA_.NAFSI.M2_SAR_PERSON_T1', 'KISW.G2.SARUFI.T1_MATUMIZI_YA_WEWE_NA_.NAFSI', 'Repeats the pronoun of the question in the answer (Wewe unaenda wapi? Wewe ninaenda sokoni.) instead of switching to mimi.', '{"question":"Rafiki anakuuliza: \"Wewe unaitwa nani?\" Unajibu:","wrong_answer":"Wewe unaitwa Baraka.","correct_answer":"Mimi ninaitwa Baraka."}'::jsonb, 'The child copies the words he heard; changing person between speakers is new.', 'The question "Rafiki anakuuliza: "Wewe unaitwa nani?" Unajibu:" with "Wewe unaitwa Baraka." among the options.', 'Ask and answer in pairs with a pointing finger: wewe points out, mimi points to the chest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T1_MATUMIZI_YA_WEWE_NA_.NAFSI.M2_SAR_OBJ_T1', 'KISW.G2.SARUFI.T1_MATUMIZI_YA_WEWE_NA_.NAFSI', 'Puts the pronoun after the verb instead of the object marker inside it (Mama alimpa mimi for Mama alinipa).', '{"question":"Ni lipi sahihi?","wrong_answer":"Nitampa wewe kalamu.","correct_answer":"Nitakupa kalamu."}'::jsonb, 'English says "gave me"; the child adds the separate word instead of -ni- inside the verb.', 'The question "Ni lipi sahihi?" with "Nitampa wewe kalamu." among the options.', 'Show the verb with the object marker coloured: a-li-ni-pa; compare with the wrong form.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI.M2_SAU_NEAR_T2', 'KISW.G2.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI', 'Says /w/ for /mw/, so "mwezi" becomes "wezi".', '{"question":"Mwalimu anasema \"mwezi\". Neno lipi limetamkwa vizuri?","wrong_answer":"wezi","correct_answer":"mwezi"}'::jsonb, 'Many Kenyan first languages have no /mw/, or do not separate it from /w/; the child puts in the home sound.', 'The question "Mwalimu anasema "mwezi". Neno lipi limetamkwa vizuri?" with "wezi" among the options.', 'Say the two side by side, slowly, watching the mouth; the child holds up a card for the sound he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI.M2_SAU_VOWEL_T2', 'KISW.G2.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI', 'Pushes a vowel into the cluster, so "mwalimu" is said "muwalimu".', '{"question":"Tamka neno \"mwalimu\". Ni lipi sahihi?","wrong_answer":"muwalimu","correct_answer":"mwalimu"}'::jsonb, 'In the child''s first language, or in English loan habits, two consonants rarely sit together; he breaks them with a vowel.', 'The question "Tamka neno "mwalimu". Ni lipi sahihi?" with "muwalimu" among the options.', 'Say the cluster in one beat, then the word; clap once for the cluster syllable.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI.M2_SAU_DROP_T2', 'KISW.G2.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI', 'Drops part of the target sound, so "njia" becomes "jia".', '{"question":"Neno \"njia\" limeandikwa au kutamkwa vipi kwa usahihi?","wrong_answer":"jia","correct_answer":"njia"}'::jsonb, 'The second part of the sound (the w or y glide, or the soft nasal) is quick and quiet; the child does not hear it and leaves it out.', 'The question "Neno "njia" limeandikwa au kutamkwa vipi kwa usahihi?" with "jia" among the options.', 'Stretch the syllable slowly (p-y-a), then say it fast; the child copies.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI.M2_SAU_SYLL_T2', 'KISW.G2.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI', 'Splits "mwalimu" by letters rather than by syllables (each Kiswahili syllable ends in a vowel).', '{"question":"Neno \"mwalimu\" lina silabi zipi?","wrong_answer":"m-w-a-l-i-m-u","correct_answer":"mwa-li-mu"}'::jsonb, 'The child has learnt letters one by one and has not been shown that a syllable is a sound that ends in a vowel.', 'The question "Neno "mwalimu" lina silabi zipi?" with "m-w-a-l-i-m-u" among the options.', 'Clap the word: one clap per vowel; the consonants go with the vowel after them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI.M2_SAU_PICK_T2', 'KISW.G2.KUSIKI.T2_MATAMSHI_BORA.MATAMSHI', 'Picks a word with no target sound when asked for one that has it.', '{"question":"Ni neno lipi lina sauti /mw/, /nj/?","wrong_answer":"kalamu","correct_answer":"njia"}'::jsonb, 'The child looks at the first letter or the picture, not at the sound.', 'The question "Ni neno lipi lina sauti /mw/, /nj/?" with "kalamu" among the options.', 'Underline the target sound in each word on the card before choosing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_SOUND_T2', 'KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads the target word wrongly: "mwanafunzi" as "muwanafunzi".', '{"question":"Neno \"mwanafunzi\" linasomwa vipi?","wrong_answer":"muwanafunzi","correct_answer":"mwanafunzi"}'::jsonb, 'The child reads the letters with the sounds of his first language, or adds a vowel to break the cluster.', 'The question "Neno "mwanafunzi" linasomwa vipi?" with "muwanafunzi" among the options.', 'Pick out the target words before reading; practise them on cards, then read the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_WORD_T2', 'KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Kila mtoto ana haki ya chakula.\"?","wrong_answer":"Kila ... mtoto ... ana ... haki ... ya ... chakula.","correct_answer":"Kila mtoto ana haki ya chakula."}'::jsonb, 'The child is still decoding each word; he has not yet read a group of words as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Kila mtoto ana haki ya chakula."?" with "Kila ... mtoto ... ana ... haki ... ya ... chakula." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it in one breath.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_QUIET_T2', 'KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads so softly (or so loudly, shouting) that the class cannot follow.', '{"question":"Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?","wrong_answer":"ya chini ili nisikosee mbele ya wenzangu","correct_answer":"ya kusikika na wote darasani, bila kupiga kelele"}'::jsonb, 'Shyness, or the belief that reading well means reading loud.', 'The question "Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?" with "ya chini ili nisikosee mbele ya wenzangu" among the options.', 'Stand the reader at the front and a listener at the back: the listener raises a hand when he hears every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_PACE_T2', 'KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Kasi ifaayo ya kusoma kifungu ni ipi?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, karibu maneno 33 kwa dakika"}'::jsonb, 'Reading races in class reward speed; nobody asked whether the listeners understood.', 'The question "Kasi ifaayo ya kusoma kifungu ni ipi?" with "haraka iwezekanavyo" among the options.', 'Time two readings, one very fast and one at speaking pace; the listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_MARK_T2', 'KISW.G2.KUSOMA.T2_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question in the flat voice of a statement and runs on through the koma and kikomo.', '{"question":"Sentensi \"Je, una nguo safi?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the marks.', 'The question "Sentensi "Je, una nguo safi?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that fits each reading; clap at each kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU.M2_HAT_CAPSTART_T2', 'KISW.G2.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'Starts a sentence or a name with a small letter.', '{"question":"Andika kwa usahihi: mwalimu akinyi anafundisha darasa la pili.","wrong_answer":"mwalimu akinyi anafundisha darasa la pili.","correct_answer":"Mwalimu Akinyi anafundisha darasa la pili."}'::jsonb, 'The child copies words, not sentences; the rule that a sentence and a name begin with a capital is not yet used.', 'The question "Andika kwa usahihi: mwalimu akinyi anafundisha darasa la pili." with "mwalimu akinyi anafundisha darasa la pili." among the options.', 'Circle the first letter of each sentence and each name in a passage in red.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU.M2_HAT_CAPMID_T2', 'KISW.G2.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'Puts capital letters in the middle of words (JuMa, Kitabu KiKubwa).', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"JuMa ANakula","correct_answer":"Juma anakula"}'::jsonb, 'Some capitals (K, M, S) are easier to form than the small letter, so the child uses them anywhere.', 'The question "Ni lipi limeandikwa vizuri?" with "JuMa ANakula" among the options.', 'Sort letter cards: capital only at the start; the rest small.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU.M2_HAT_SPACE_T2', 'KISW.G2.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'Leaves no space between words (Mamaanapika).', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"Mamaanapikachakula.","correct_answer":"Mama anapika chakula."}'::jsonb, 'Spoken Kiswahili runs words together; the child writes the stream as he hears it.', 'The question "Ni lipi limeandikwa vizuri?" with "Mamaanapikachakula." among the options.', 'Put a finger space after every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU.M2_HAT_TURN_T2', 'KISW.G2.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'Turns b and d (or p and q) round: dada written "baba" or "bada".', '{"question":"Andika neno \"dada\".","wrong_answer":"bada","correct_answer":"dada"}'::jsonb, 'Mirror letters are common in early writing; the child has not fixed the direction.', 'The question "Andika neno "dada"." with "bada" among the options.', 'Teach d as "c then a tall line"; trace it in sand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU.M2_HAT_LINE_T2', 'KISW.G2.KUANDI.T2_HATI_NADHIFU_HERUFI_.HATI_NADHIFU', 'Writes letters floating above the line or of mixed sizes, so the line goes up and down.', '{"question":"Maandishi nadhifu yanakaa wapi?","wrong_answer":"popote kwenye ukurasa","correct_answer":"juu ya mstari, herufi zikiwa na ukubwa sawa"}'::jsonb, 'The child writes fast and does not look at the line.', 'The question "Maandishi nadhifu yanakaa wapi?" with "popote kwenye ukurasa" among the options.', 'Trace the line with a finger first; every letter sits on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T2_UMOJA_NA_WINGI_WA_VI.UMOJA_WINGI.M2_SAR_WRONGCLASS_T2', 'KISW.G2.SARUFI.T2_UMOJA_NA_WINGI_WA_VI.UMOJA_WINGI', 'Makes the plural with the prefix of another noun class (kitabu -> watabu).', '{"question":"Wingi wa \"kitanda changu\" ni?","wrong_answer":"watanda wetu","correct_answer":"vitanda vyetu"}'::jsonb, 'The child knows that wa- makes people plural and uses it for everything; the ngeli of the noun is not yet known.', 'The question "Wingi wa "kitanda changu" ni?" with "watanda wetu" among the options.', 'Sort noun cards into ngeli families (m-wa, ki-vi, li-ma, n-n) and say each plural aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T2_UMOJA_NA_WINGI_WA_VI.UMOJA_WINGI.M2_SAR_NUMPOSS_T2', 'KISW.G2.SARUFI.T2_UMOJA_NA_WINGI_WA_VI.UMOJA_WINGI', 'Leaves the possessive singular with a plural noun (vitabu changu).', '{"question":"Wingi wa \"kiatu changu\" ni?","wrong_answer":"viatu changu","correct_answer":"viatu vyetu"}'::jsonb, 'The child changes the noun and forgets the possessive.', 'The question "Wingi wa "kiatu changu" ni?" with "viatu changu" among the options.', 'Change one object to many in front of the child; both words change.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T2_UMOJA_NA_WINGI_WA_VI.UMOJA_WINGI.M2_SAR_NUMWORD_T2', 'KISW.G2.SARUFI.T2_UMOJA_NA_WINGI_WA_VI.UMOJA_WINGI', 'Shows the plural only with a number word and leaves the noun singular (kitabu mbili).', '{"question":"Wingi wa \"kikombe kimoja\" ni?","wrong_answer":"kikombe viwili","correct_answer":"vikombe viwili"}'::jsonb, 'English and some first languages keep the noun and add a number; Kiswahili changes the noun and the number agrees.', 'The question "Wingi wa "kikombe kimoja" ni?" with "kikombe viwili" among the options.', 'Line up two books: the child says vitabu viwili; then three: vitabu vitatu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T2_UMOJA_NA_WINGI_WA_VI.UMOJA_WINGI.M2_SAR_REVERSE_T2', 'KISW.G2.SARUFI.T2_UMOJA_NA_WINGI_WA_VI.UMOJA_WINGI', 'Takes the plural form for the singular (miti for one tree, vitabu for one book).', '{"question":"Ni kifungu kipi kiko katika umoja?","wrong_answer":"vyakula vyetu","correct_answer":"chakula changu"}'::jsonb, 'The child heard the plural more often (a tree is usually among trees) and learnt it as the name.', 'The question "Ni kifungu kipi kiko katika umoja?" with "vyakula vyetu" among the options.', 'Hold one object, then many; the child names each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T2_UMOJA_NA_WINGI_WA_VI.UMOJA_WINGI.M2_SAR_CONCPOSS_T2', 'KISW.G2.SARUFI.T2_UMOJA_NA_WINGI_WA_VI.UMOJA_WINGI', 'Uses the wrong noun-class form of the possessive (kitabu yangu for kitabu changu).', '{"question":"Jaza: chakula ___ (-angu)","wrong_answer":"yangu","correct_answer":"changu"}'::jsonb, 'Town Kiswahili uses yangu, yako, yake for every noun; the child has not seen the ngeli agreement.', 'The question "Jaza: chakula ___ (-angu)" with "yangu" among the options.', 'Pair nouns and possessives by colour: kitabu changu, kiti chake, mtoto wangu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA.M2_HES_POLE_T3', 'KISW.G2.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA', 'Says samahani when someone else is hurt by accident, where pole (sympathy) is meant.', '{"question":"Rafiki ameanguka mwenyewe uwanjani. Unamwambia nini?","wrong_answer":"Samahani","correct_answer":"Pole"}'::jsonb, 'English "sorry" covers both apology and sympathy; Kiswahili separates them: samahani when I did wrong, pole when you suffer.', 'The question "Rafiki ameanguka mwenyewe uwanjani. Unamwambia nini?" with "Samahani" among the options.', 'Two pictures: I stepped on your foot (samahani); you fell by yourself (pole). The child names each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA.M2_HES_KARIBU_T3', 'KISW.G2.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA', 'Answers "Asante" with "Asante" instead of "Karibu" (or "Si neno").', '{"question":"Ulimpa rafiki kalamu, akasema \"Asante.\" Unajibu nini?","wrong_answer":"Asante","correct_answer":"Karibu"}'::jsonb, 'The child echoes the polite word he has just heard.', 'The question "Ulimpa rafiki kalamu, akasema "Asante." Unajibu nini?" with "Asante" among the options.', 'Practise the pair with two children: one gives, one thanks, the giver answers Karibu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA.M2_HES_COMMAND_T3', 'KISW.G2.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA', 'Asks with a bare command (Nipe maji!) without tafadhali or naomba.', '{"question":"Unataka maji kutoka kwa mama. Unasemaje?","wrong_answer":"Nipe maji!","correct_answer":"Mama, tafadhali naomba maji."}'::jsonb, 'At home and in play the child hears short commands and copies them to adults.', 'The question "Unataka maji kutoka kwa mama. Unasemaje?" with "Nipe maji!" among the options.', 'Say both versions; the child says which one makes mama want to help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA.M2_HES_TITLE_T3', 'KISW.G2.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA', 'Calls an adult by the bare first name without a title (Mwalimu, Mama, Baba, Bi., Bw.).', '{"question":"Unamwita mwalimu wako, Bi. Akinyi. Unasemaje?","wrong_answer":"Akinyi, njoo!","correct_answer":"Mwalimu, tafadhali njoo."}'::jsonb, 'Children call each other by name and carry the habit to adults.', 'The question "Unamwita mwalimu wako, Bi. Akinyi. Unasemaje?" with "Akinyi, njoo!" among the options.', 'Make title cards (Mwalimu, Mama, Babu, Daktari); the child puts one before each name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA.M2_HES_POLEREPLY_T3', 'KISW.G2.KUSIKI.T3_MANENO_YA_HESHIMA_NA.HESHIMA', 'Answers "Pole" with "Pole" instead of "Asante".', '{"question":"Rafiki anakuambia \"Pole kwa kuumia.\" Unajibu?","wrong_answer":"Pole","correct_answer":"Asante"}'::jsonb, 'The child echoes the word, as with greetings.', 'The question "Rafiki anakuambia "Pole kwa kuumia." Unajibu?" with "Pole" among the options.', 'Act it: one child is hurt, the other says pole, the hurt one says asante.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T3_KUSOMA_KWA_UFAHAMU_K.UFAHAMU.M2_UFM_WORD_T3', 'KISW.G2.KUSOMA.T3_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'Gives "afya" the meaning of a word that looks or sounds like it.', '{"question":"Soma: \"Kila asubuhi, Baraka hula uji na ndizi. Mchana hula wali, maharagwe na mboga. Mama husema chakula bora hutupa nguvu na afya.\" Neno \"afya\" lina maana gani?","wrong_answer":"nyanya","correct_answer":"hali ya mwili kuwa mzima bila ugonjwa"}'::jsonb, 'The child matches the word to a known one by its look instead of reading the sentence around it.', 'The question "Soma: "Kila asubuhi, Baraka hula uji na ndizi. Mchana hula wali, maharagwe na mboga. Mama husema chakula bora hutupa nguvu na afya." Neno "afya" lina maana gani?" with "nyanya" among the options.', 'Cover the word; the child says what word would fit the sentence, then uncovers it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T3_KUSOMA_KWA_UFAHAMU_K.UFAHAMU.M2_UFM_MSG_T3', 'KISW.G2.KUSOMA.T3_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'Gives one detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ni upi?","wrong_answer":"Baraka hula uji asubuhi.","correct_answer":"Tule chakula bora ili tuwe na nguvu na afya."}'::jsonb, 'The detail is what the child remembers best; he has not been asked what the writer wants us to know.', 'The question "Ujumbe wa kifungu ni upi?" with "Baraka hula uji asubuhi." among the options.', 'Ask two questions side by side: "Nini kilitokea?" and "Kifungu kinatuambia nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T3_KUSOMA_KWA_UFAHAMU_K.UFAHAMU.M2_UFM_GUESS_T3', 'KISW.G2.KUSOMA.T3_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'Predicts something the passage gives no clue for, without looking at the picture.', '{"question":"Picha inaonyesha Baraka akikataa mboga. Mama atafanya nini?","wrong_answer":"Atampa pipi.","correct_answer":"Atamweleza umuhimu wa kula mboga."}'::jsonb, 'Prediction is taken as free imagination; the child has not been shown that clues in the text and picture point the way.', 'The question "Picha inaonyesha Baraka akikataa mboga. Mama atafanya nini?" with "Atampa pipi." among the options.', 'Underline the clue words and point at the picture; the guess must fit them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T3_KUSOMA_KWA_UFAHAMU_K.UFAHAMU.M2_UFM_LESSON_T3', 'KISW.G2.KUSOMA.T3_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'Retells what happened when asked for the lesson.', '{"question":"Tunajifunza nini kutokana na kifungu?","wrong_answer":"Baraka hula wali mchana.","correct_answer":"Tunapaswa kula vyakula vya aina mbalimbali."}'::jsonb, 'The lesson question sounds like a what-happened question to the child.', 'The question "Tunajifunza nini kutokana na kifungu?" with "Baraka hula wali mchana." among the options.', 'Start the answer with "Tunajifunza kwamba tunapaswa..."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T3_KUSOMA_KWA_UFAHAMU_K.UFAHAMU.M2_UFM_OWN_T3', 'KISW.G2.KUSOMA.T3_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'Answers from his own life instead of from the passage.', '{"question":"Baraka hula nini asubuhi?","wrong_answer":"Mimi hunywa chai.","correct_answer":"uji na ndizi"}'::jsonb, 'The child links the question to what he knows from home and does not check the text.', 'The question "Baraka hula nini asubuhi?" with "Mimi hunywa chai." among the options.', 'Ask the child to point at the line in the passage that gives the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T3_MPANGILIO_WA_HERUFI_.HATI_NADHIFU.M2_HAT_TALL_T3', 'KISW.G2.KUANDI.T3_MPANGILIO_WA_HERUFI_.HATI_NADHIFU', 'Writes the tall small letters (b, d, h, k, l) short, so h looks like n.', '{"question":"Andika neno \"habari\". Ni lipi limeandikwa vizuri?","wrong_answer":"nabari","correct_answer":"habari"}'::jsonb, 'The child does not use the lines of the book: tall letters must reach the top line.', 'The question "Andika neno "habari". Ni lipi limeandikwa vizuri?" with "nabari" among the options.', 'Write on three-line paper; the child colours the part of h that goes up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T3_MPANGILIO_WA_HERUFI_.HATI_NADHIFU.M2_HAT_SIZE_T3', 'KISW.G2.KUANDI.T3_MPANGILIO_WA_HERUFI_.HATI_NADHIFU', 'Writes some small letters as big as capitals (kiti written kiTi or KITI).', '{"question":"Ni neno lipi limeandikwa kwa herufi ndogo vizuri?","wrong_answer":"KITI","correct_answer":"kiti"}'::jsonb, 'Capitals were learnt first in pre-primary and feel safer to write.', 'The question "Ni neno lipi limeandikwa kwa herufi ndogo vizuri?" with "KITI" among the options.', 'Compare k/K, s/S, t/T on cards; the child picks the small one for the middle of a word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T3_MPANGILIO_WA_HERUFI_.HATI_NADHIFU.M2_HAT_SPACE_T3', 'KISW.G2.KUANDI.T3_MPANGILIO_WA_HERUFI_.HATI_NADHIFU', 'Leaves no space between words (Mamaanapika).', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"Mamaanapikachakula.","correct_answer":"Mama anapika chakula."}'::jsonb, 'Spoken Kiswahili runs words together; the child writes the stream as he hears it.', 'The question "Ni lipi limeandikwa vizuri?" with "Mamaanapikachakula." among the options.', 'Put a finger space after every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T3_MPANGILIO_WA_HERUFI_.HATI_NADHIFU.M2_HAT_TURN_T3', 'KISW.G2.KUANDI.T3_MPANGILIO_WA_HERUFI_.HATI_NADHIFU', 'Turns b and d (or p and q) round: dada written "baba" or "bada".', '{"question":"Andika neno \"dada\".","wrong_answer":"bada","correct_answer":"dada"}'::jsonb, 'Mirror letters are common in early writing; the child has not fixed the direction.', 'The question "Andika neno "dada"." with "bada" among the options.', 'Teach d as "c then a tall line"; trace it in sand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T3_MPANGILIO_WA_HERUFI_.HATI_NADHIFU.M2_HAT_LINE_T3', 'KISW.G2.KUANDI.T3_MPANGILIO_WA_HERUFI_.HATI_NADHIFU', 'Writes letters floating above the line or of mixed sizes, so the line goes up and down.', '{"question":"Maandishi nadhifu yanakaa wapi?","wrong_answer":"popote kwenye ukurasa","correct_answer":"juu ya mstari, herufi zikiwa na ukubwa sawa"}'::jsonb, 'The child writes fast and does not look at the line.', 'The question "Maandishi nadhifu yanakaa wapi?" with "popote kwenye ukurasa" among the options.', 'Trace the line with a finger first; every letter sits on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T3_MATUMIZI_YA_HUYO_NA_.VIONYESHI.M2_SAR_CLASSDEM_T3', 'KISW.G2.SARUFI.T3_MATUMIZI_YA_HUYO_NA_.VIONYESHI', 'Uses the people word (huyu, yule) for a thing (kiti huyu).', '{"question":"Jaza: Kikombe ___ (kilicho karibu nawe) ni chako.","wrong_answer":"huyo","correct_answer":"hicho"}'::jsonb, 'Huyu was the first pointing word learnt; the child uses it for anything.', 'The question "Jaza: Kikombe ___ (kilicho karibu nawe) ni chako." with "huyo" among the options.', 'Point at a child (huyu) and at a chair (hiki); then sort pictures by the pointing word they take.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T3_MATUMIZI_YA_HUYO_NA_.VIONYESHI.M2_SAR_NUMDEM_T3', 'KISW.G2.SARUFI.T3_MATUMIZI_YA_HUYO_NA_.VIONYESHI', 'Uses the one-thing pointing word with a plural noun (watoto huyu).', '{"question":"Jaza: Wapishi ___ (walio karibu nawe) ni hodari.","wrong_answer":"huyo","correct_answer":"hao"}'::jsonb, 'The child changes the noun but not the pointing word.', 'The question "Jaza: Wapishi ___ (walio karibu nawe) ni hodari." with "huyo" among the options.', 'Pair the forms on cards: huyu-hawa, yule-wale, hiki-hivi, hili-haya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T3_MATUMIZI_YA_HUYO_NA_.VIONYESHI.M2_SAR_DIST_T3', 'KISW.G2.SARUFI.T3_MATUMIZI_YA_HUYO_NA_.VIONYESHI', 'Mixes near and far pointing words (huyu for someone far away; yule for someone close).', '{"question":"Mtoto amesimama karibu nami. Ninasema: Mtoto ___ ni dada yangu.","wrong_answer":"huyo","correct_answer":"huyu"}'::jsonb, 'The child has not linked the forms to distance from the speaker.', 'The question "Mtoto amesimama karibu nami. Ninasema: Mtoto ___ ni dada yangu." with "huyo" among the options.', 'Stand near one child and far from another; point and say huyu and yule; then swap places.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T3_MATUMIZI_YA_HUYO_NA_.VIONYESHI.M2_SAR_HII_T3', 'KISW.G2.SARUFI.T3_MATUMIZI_YA_HUYO_NA_.VIONYESHI', 'Uses hii for every noun (kitabu hii, mtoto hii), as in town Kiswahili.', '{"question":"Jaza: Mama ___ (aliye karibu nawe) anauza matunda.","wrong_answer":"hii","correct_answer":"huyo"}'::jsonb, 'Hii is the pointing word heard most in town speech, where the noun class is dropped.', 'The question "Jaza: Mama ___ (aliye karibu nawe) anauza matunda." with "hii" among the options.', 'Read pairs aloud: kitabu hiki, mtoto huyu, nyumba hii; the child hears the match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI.M2_SAU_NEAR_T4', 'KISW.G2.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'Says /z/ for /dh/, so "dhoruba" becomes "zoruba".', '{"question":"Mwalimu anasema \"dhoruba\". Neno lipi limetamkwa vizuri?","wrong_answer":"zoruba","correct_answer":"dhoruba"}'::jsonb, 'Many Kenyan first languages have no /dh/, or do not separate it from /z/; the child puts in the home sound.', 'The question "Mwalimu anasema "dhoruba". Neno lipi limetamkwa vizuri?" with "zoruba" among the options.', 'Say the two side by side, slowly, watching the mouth; the child holds up a card for the sound he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI.M2_SAU_NEAR2_T4', 'KISW.G2.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'Says /sh/ for /ch/, so "chombo" becomes "shombo".', '{"question":"Neno lipi limetamkwa vizuri?","wrong_answer":"shombo","correct_answer":"chombo"}'::jsonb, '/ch/ and /sh/ are close; a first language with only one of them puts that one in both places.', 'The question "Neno lipi limetamkwa vizuri?" with "shombo" among the options.', 'Contrast the two with a mirror and a hand before the mouth; the child says which he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI.M2_SAU_DROP_T4', 'KISW.G2.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'Drops part of the target sound, so "dhahabu" becomes "dahabu".', '{"question":"Neno \"dhahabu\" limeandikwa au kutamkwa vipi kwa usahihi?","wrong_answer":"dahabu","correct_answer":"dhahabu"}'::jsonb, 'The second part of the sound (the w or y glide, or the soft nasal) is quick and quiet; the child does not hear it and leaves it out.', 'The question "Neno "dhahabu" limeandikwa au kutamkwa vipi kwa usahihi?" with "dahabu" among the options.', 'Stretch the syllable slowly (p-y-a), then say it fast; the child copies.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI.M2_SAU_SYLL_T4', 'KISW.G2.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'Splits "chombo" by letters rather than by syllables (each Kiswahili syllable ends in a vowel).', '{"question":"Neno \"chombo\" lina silabi zipi?","wrong_answer":"c-h-o-m-b-o","correct_answer":"cho-mbo"}'::jsonb, 'The child has learnt letters one by one and has not been shown that a syllable is a sound that ends in a vowel.', 'The question "Neno "chombo" lina silabi zipi?" with "c-h-o-m-b-o" among the options.', 'Clap the word: one clap per vowel; the consonants go with the vowel after them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI.M2_SAU_PICK_T4', 'KISW.G2.KUSIKI.T4_MATAMSHI_BORA_SAUTI_.MATAMSHI', 'Picks a word with no target sound when asked for one that has it.', '{"question":"Ni neno lipi lina sauti /ch/, /dh/?","wrong_answer":"basi","correct_answer":"dhoruba"}'::jsonb, 'The child looks at the first letter or the picture, not at the sound.', 'The question "Ni neno lipi lina sauti /ch/, /dh/?" with "basi" among the options.', 'Underline the target sound in each word on the card before choosing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI.M2_UFS_SOUND_T4', 'KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'Reads the target word wrongly: "dhahabu" as "zahabu".', '{"question":"Neno \"dhahabu\" linasomwa vipi?","wrong_answer":"zahabu","correct_answer":"dhahabu"}'::jsonb, 'The child reads the letters with the sounds of his first language, or adds a vowel to break the cluster.', 'The question "Neno "dhahabu" linasomwa vipi?" with "zahabu" among the options.', 'Pick out the target words before reading; practise them on cards, then read the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI.M2_UFS_WORD_T4', 'KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Basi linabeba abiria wengi.\"?","wrong_answer":"Basi ... linabeba ... abiria ... wengi.","correct_answer":"Basi linabeba abiria wengi."}'::jsonb, 'The child is still decoding each word; he has not yet read a group of words as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Basi linabeba abiria wengi."?" with "Basi ... linabeba ... abiria ... wengi." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it in one breath.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI.M2_UFS_QUIET_T4', 'KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'Reads so softly (or so loudly, shouting) that the class cannot follow.', '{"question":"Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?","wrong_answer":"ya chini ili nisikosee mbele ya wenzangu","correct_answer":"ya kusikika na wote darasani, bila kupiga kelele"}'::jsonb, 'Shyness, or the belief that reading well means reading loud.', 'The question "Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?" with "ya chini ili nisikosee mbele ya wenzangu" among the options.', 'Stand the reader at the front and a listener at the back: the listener raises a hand when he hears every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI.M2_UFS_PACE_T4', 'KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Kasi ifaayo ya kusoma kifungu ni ipi?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, karibu maneno 36 kwa dakika"}'::jsonb, 'Reading races in class reward speed; nobody asked whether the listeners understood.', 'The question "Kasi ifaayo ya kusoma kifungu ni ipi?" with "haraka iwezekanavyo" among the options.', 'Time two readings, one very fast and one at speaking pace; the listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI.M2_UFS_MARK_T4', 'KISW.G2.KUSOMA.T4_KUSOMA_KWA_UFASAHA_S.KUSOMA_KWA_SAUTI', 'Reads a question in the flat voice of a statement and runs on through the koma and kikomo.', '{"question":"Sentensi \"Je, dereva amefunga mkanda?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the marks.', 'The question "Sentensi "Je, dereva amefunga mkanda?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that fits each reading; clap at each kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T4_NAFASI_KATIKA_MAANDI.NAFASI_KATI_YA_MANENO.M2_NAF_NONE_T4', 'KISW.G2.KUANDI.T4_NAFASI_KATIKA_MAANDI.NAFASI_KATI_YA_MANENO', 'Leaves no space between words (Basilimefika).', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"Basilimefikamapema.","correct_answer":"Basi limefika mapema."}'::jsonb, 'Speech runs words together and the child writes the stream as he hears it.', 'The question "Ni lipi limeandikwa vizuri?" with "Basilimefikamapema." among the options.', 'Put a finger space after each word; count the words aloud first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T4_NAFASI_KATIKA_MAANDI.NAFASI_KATI_YA_MANENO.M2_NAF_SPLIT_T4', 'KISW.G2.KUANDI.T4_NAFASI_KATIKA_MAANDI.NAFASI_KATI_YA_MANENO', 'Splits the verb into its parts (ni na kwenda, a li fika).', '{"question":"Ni lipi sahihi?","wrong_answer":"Mimi ni na kwenda sokoni.","correct_answer":"Mimi ninakwenda sokoni."}'::jsonb, 'The child hears the parts of the verb as separate sounds and writes a space after each.', 'The question "Ni lipi sahihi?" with "Mimi ni na kwenda sokoni." among the options.', 'Underline the whole verb in one line; it is one word however long.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T4_NAFASI_KATIKA_MAANDI.NAFASI_KATI_YA_MANENO.M2_NAF_INSIDE_T4', 'KISW.G2.KUANDI.T4_NAFASI_KATIKA_MAANDI.NAFASI_KATI_YA_MANENO', 'Puts a space inside a word at a syllable (ba si, ga ri).', '{"question":"Ni lipi sahihi?","wrong_answer":"Ga ri ni jekundu.","correct_answer":"Gari ni jekundu."}'::jsonb, 'The child has learnt to write syllable by syllable and leaves a gap after each.', 'The question "Ni lipi sahihi?" with "Ga ri ni jekundu." among the options.', 'Write the syllables close together and read the word aloud; then the gap goes after the word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T4_NAFASI_KATIKA_MAANDI.NAFASI_KATI_YA_MANENO.M2_NAF_UNEVEN_T4', 'KISW.G2.KUANDI.T4_NAFASI_KATIKA_MAANDI.NAFASI_KATI_YA_MANENO', 'Leaves very large gaps between some words and none between others.', '{"question":"Nafasi kati ya maneno inafaa kuwa vipi?","wrong_answer":"yoyote, kubwa au ndogo","correct_answer":"sawa, kama kidole kimoja"}'::jsonb, 'The child does not measure; he writes as space allows on the line.', 'The question "Nafasi kati ya maneno inafaa kuwa vipi?" with "yoyote, kubwa au ndogo" among the options.', 'Use a finger or a lolly stick as the measure for each gap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T4_UMOJA_NA_WINGI.UMOJA_WINGI.M2_SAR_WRONGCLASS_T4', 'KISW.G2.SARUFI.T4_UMOJA_NA_WINGI.UMOJA_WINGI', 'Makes the plural with the prefix of another noun class (kitabu -> watabu).', '{"question":"Wingi wa \"mwendeshaji\" ni?","wrong_answer":"miendeshaji","correct_answer":"waendeshaji"}'::jsonb, 'The child knows that wa- makes people plural and uses it for everything; the ngeli of the noun is not yet known.', 'The question "Wingi wa "mwendeshaji" ni?" with "miendeshaji" among the options.', 'Sort noun cards into ngeli families (m-wa, ki-vi, li-ma, n-n) and say each plural aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T4_UMOJA_NA_WINGI.UMOJA_WINGI.M2_SAR_NCLASS_T4', 'KISW.G2.SARUFI.T4_UMOJA_NA_WINGI.UMOJA_WINGI', 'Gives a noun of the n-n class a plural prefix (nyumba -> manyumba), or changes an irregular noun wrongly (jicho -> majicho).', '{"question":"Wingi wa \"ndege moja\" ni?","wrong_answer":"mandege mawili","correct_answer":"ndege mbili"}'::jsonb, 'The child expects every plural to look different; n-n nouns stay the same and some li-ma nouns change their stem.', 'The question "Wingi wa "ndege moja" ni?" with "mandege mawili" among the options.', 'Keep a short list of the same-in-both nouns (nyumba, ndizi, kalamu) and the irregular ones (jicho - macho, jino - meno).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T4_UMOJA_NA_WINGI.UMOJA_WINGI.M2_SAR_NUMWORD_T4', 'KISW.G2.SARUFI.T4_UMOJA_NA_WINGI.UMOJA_WINGI', 'Shows the plural only with a number word and leaves the noun singular (kitabu mbili).', '{"question":"Wingi wa \"gari moja\" ni?","wrong_answer":"gari mbili","correct_answer":"magari mawili"}'::jsonb, 'English and some first languages keep the noun and add a number; Kiswahili changes the noun and the number agrees.', 'The question "Wingi wa "gari moja" ni?" with "gari mbili" among the options.', 'Line up two books: the child says vitabu viwili; then three: vitabu vitatu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T4_UMOJA_NA_WINGI.UMOJA_WINGI.M2_SAR_REVERSE_T4', 'KISW.G2.SARUFI.T4_UMOJA_NA_WINGI.UMOJA_WINGI', 'Takes the plural form for the singular (miti for one tree, vitabu for one book).', '{"question":"Ni lipi liko katika umoja?","wrong_answer":"magari","correct_answer":"gari"}'::jsonb, 'The child heard the plural more often (a tree is usually among trees) and learnt it as the name.', 'The question "Ni lipi liko katika umoja?" with "magari" among the options.', 'Hold one object, then many; the child names each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T4_UMOJA_NA_WINGI.UMOJA_WINGI.M2_SAR_PLADJ_T4', 'KISW.G2.SARUFI.T4_UMOJA_NA_WINGI.UMOJA_WINGI', 'Leaves the adjective singular with a plural noun (watoto mzuri).', '{"question":"Wingi wa \"basi kubwa\" ni?","wrong_answer":"mabasi kubwa","correct_answer":"mabasi makubwa"}'::jsonb, 'The child changes the noun only.', 'The question "Wingi wa "basi kubwa" ni?" with "mabasi kubwa" among the options.', 'Change the noun to many and ask the child to change every word that goes with it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M2_SIK_DETAIL_T5', 'KISW.G2.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Gives a detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ulichosikiliza ni upi?","wrong_answer":"Sungura alikuwa na chakula.","correct_answer":"Akili hutusaidia kujiokoa tukiwa hatarini."}'::jsonb, 'The detail is the clearest thing the child remembers; he has not been asked what the passage teaches.', 'The question "Ujumbe wa kifungu ulichosikiliza ni upi?" with "Sungura alikuwa na chakula." among the options.', 'After listening, ask "Kifungu kinatufundisha nini?" and compare it with "Nini kilitokea?".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M2_SIK_WORD_T5', 'KISW.G2.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Gives "mjanja" the meaning of a word that sounds like it.', '{"question":"Neno \"mjanja\" katika kifungu lina maana gani?","wrong_answer":"mjinga","correct_answer":"mwenye akili ya kutafuta njia"}'::jsonb, 'The child matches the sound of the word to one he knows instead of listening to the sentence around it.', 'The question "Neno "mjanja" katika kifungu lina maana gani?" with "mjinga" among the options.', 'Replay the sentence; the child tries each meaning in it and keeps the one that makes sense.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M2_SIK_SENT_T5', 'KISW.G2.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Makes a "sentence" that only repeats the word and shows no meaning (mjanja ni mjanja).', '{"question":"Ni sentensi ipi inaonyesha maana ya \"mjanja\"?","wrong_answer":"Mjanja ni mjanja.","correct_answer":"Sungura mjanja alitafuta njia ya kumtoroka fisi."}'::jsonb, 'The child thinks any sentence with the word in it is enough.', 'The question "Ni sentensi ipi inaonyesha maana ya "mjanja"?" with "Mjanja ni mjanja." among the options.', 'Ask: if your friend did not know the word, would your sentence tell him what it means?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M2_SIK_ORDER_T5', 'KISW.G2.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Retells the events out of order.', '{"question":"Panga matukio ya kifungu kama yalivyotokea.","wrong_answer":"Sungura alitoroka, fisi alimkuta sungura, sungura alimdanganya fisi","correct_answer":"Fisi alimkuta sungura, sungura alimdanganya fisi, sungura akatoroka"}'::jsonb, 'The child remembers the most exciting event and tells it first.', 'The question "Panga matukio ya kifungu kama yalivyotokea." with "Sungura alitoroka, fisi alimkuta sungura, sungura alimdanganya fisi" among the options.', 'Three picture cards of the events; the child lays them left to right and retells with kwanza, kisha, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA.M2_SIK_ADD_T5', 'KISW.G2.KUSIKI.T5_UFAHAMU_WA_KUSIKILIZ.UFAHAMU_KUSIKILIZA', 'Adds events that were not in the passage when retelling.', '{"question":"Unaposimulia upya, unaongeza mambo ambayo hayakuwa kwenye kifungu?","wrong_answer":"ndiyo, ili hadithi iwe tamu","correct_answer":"hapana, ninasimulia yaliyokuwemo tu"}'::jsonb, 'Retelling is taken as storytelling: the child invents to make it longer.', 'The question "Unaposimulia upya, unaongeza mambo ambayo hayakuwa kwenye kifungu?" with "ndiyo, ili hadithi iwe tamu" among the options.', 'After the retelling, the class checks each event: was it in the passage? Thumbs up or down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU.M2_UFM_WORD_T5', 'KISW.G2.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives "hulinda" the meaning of a word that looks or sounds like it.', '{"question":"Soma: \"Kiprono ana mbwa anayeitwa Simba. Kila siku humpa chakula na maji. Usiku, Simba hulinda nyumba dhidi ya wezi.\" Neno \"hulinda\" lina maana gani?","wrong_answer":"hulima","correct_answer":"huangalia ili pasiwe na hatari"}'::jsonb, 'The child matches the word to a known one by its look instead of reading the sentence around it.', 'The question "Soma: "Kiprono ana mbwa anayeitwa Simba. Kila siku humpa chakula na maji. Usiku, Simba hulinda nyumba dhidi ya wezi." Neno "hulinda" lina maana gani?" with "hulima" among the options.', 'Cover the word; the child says what word would fit the sentence, then uncovers it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU.M2_UFM_MSG_T5', 'KISW.G2.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives one detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ni upi?","wrong_answer":"Mbwa anaitwa Simba.","correct_answer":"Tukiwatunza wanyama wetu, nao hutusaidia."}'::jsonb, 'The detail is what the child remembers best; he has not been asked what the writer wants us to know.', 'The question "Ujumbe wa kifungu ni upi?" with "Mbwa anaitwa Simba." among the options.', 'Ask two questions side by side: "Nini kilitokea?" and "Kifungu kinatuambia nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU.M2_UFM_GUESS_T5', 'KISW.G2.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Predicts something the passage gives no clue for, without looking at the picture.', '{"question":"Picha inaonyesha mtu asiyejulikana langoni usiku. Simba atafanya nini?","wrong_answer":"Atalala.","correct_answer":"Atabweka ili kuwaamsha watu."}'::jsonb, 'Prediction is taken as free imagination; the child has not been shown that clues in the text and picture point the way.', 'The question "Picha inaonyesha mtu asiyejulikana langoni usiku. Simba atafanya nini?" with "Atalala." among the options.', 'Underline the clue words and point at the picture; the guess must fit them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU.M2_UFM_LESSON_T5', 'KISW.G2.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Retells what happened when asked for the lesson.', '{"question":"Tunajifunza nini kutokana na kifungu?","wrong_answer":"Kiprono humpa mbwa maji.","correct_answer":"Tunapaswa kuwatunza wanyama wetu."}'::jsonb, 'The lesson question sounds like a what-happened question to the child.', 'The question "Tunajifunza nini kutokana na kifungu?" with "Kiprono humpa mbwa maji." among the options.', 'Start the answer with "Tunajifunza kwamba tunapaswa..."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU.M2_UFM_OWN_T5', 'KISW.G2.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Answers from his own life instead of from the passage.', '{"question":"Mbwa wa Kiprono anaitwa nani?","wrong_answer":"Mbwa wetu anaitwa Bobi.","correct_answer":"Simba"}'::jsonb, 'The child links the question to what he knows from home and does not check the text.', 'The question "Mbwa wa Kiprono anaitwa nani?" with "Mbwa wetu anaitwa Bobi." among the options.', 'Ask the child to point at the line in the passage that gives the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T5_UAKIFISHI.ALAMA.M2_ALA_STOPQ_T5', 'KISW.G2.KUANDI.T5_UAKIFISHI.ALAMA', 'Ends a question with a kikomo.', '{"question":"Weka alama sahihi: Unaenda wapi","wrong_answer":"Unaenda wapi.","correct_answer":"Unaenda wapi?"}'::jsonb, 'The child ends every sentence the same way.', 'The question "Weka alama sahihi: Unaenda wapi" with "Unaenda wapi." among the options.', 'Read the sentence aloud: if the voice rises and asks, it takes a kiulizi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T5_UAKIFISHI.ALAMA.M2_ALA_QST_T5', 'KISW.G2.KUANDI.T5_UAKIFISHI.ALAMA', 'Puts a kiulizi after a statement.', '{"question":"Weka alama sahihi: Mimi ninaenda sokoni","wrong_answer":"Mimi ninaenda sokoni?","correct_answer":"Mimi ninaenda sokoni."}'::jsonb, 'The child uses ? as a decoration or thinks any sentence about himself is a question.', 'The question "Weka alama sahihi: Mimi ninaenda sokoni" with "Mimi ninaenda sokoni?" among the options.', 'Ask: does the sentence want an answer? If not, kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T5_UAKIFISHI.ALAMA.M2_ALA_REPORTED_T5', 'KISW.G2.KUANDI.T5_UAKIFISHI.ALAMA', 'Puts a kiulizi after a reported question (Mama aliniuliza ninaenda wapi?).', '{"question":"Weka alama sahihi: Mama aliniuliza ninaenda wapi","wrong_answer":"Mama aliniuliza ninaenda wapi?","correct_answer":"Mama aliniuliza ninaenda wapi."}'::jsonb, 'The question word wapi makes the child think the sentence is a question; it only tells that one was asked.', 'The question "Weka alama sahihi: Mama aliniuliza ninaenda wapi" with "Mama aliniuliza ninaenda wapi?" among the options.', 'Compare "Unaenda wapi?" (asked now) with "Aliniuliza ninaenda wapi." (told).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T5_UAKIFISHI.ALAMA.M2_ALA_MANY_T5', 'KISW.G2.KUANDI.T5_UAKIFISHI.ALAMA', 'Puts several kiulizi (???) for a strong question.', '{"question":"Ni lipi sahihi?","wrong_answer":"Je, sungura anakula nini???","correct_answer":"Je, sungura anakula nini?"}'::jsonb, 'Text messages and cartoons use many marks; the child copies them.', 'The question "Ni lipi sahihi?" with "Je, sungura anakula nini???" among the options.', 'One question, one kiulizi; show a page from the class reader.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T5_UAKIFISHI.ALAMA.M2_ALA_CAP_T5', 'KISW.G2.KUANDI.T5_UAKIFISHI.ALAMA', 'Writes a small letter after a kikomo or kiulizi.', '{"question":"Ni lipi sahihi?","wrong_answer":"Sungura anakula majani. mama alifurahi.","correct_answer":"Sungura anakula majani. Mama alifurahi."}'::jsonb, 'The child does not link the mark to the capital that follows it.', 'The question "Ni lipi sahihi?" with "Sungura anakula majani. mama alifurahi." among the options.', 'Every kikomo is a gate: the next word starts big.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T5_MATUMIZI_YA_AKO_NA_E.VIMILIKISHI.M2_SAR_CONCPOSS_T5', 'KISW.G2.SARUFI.T5_MATUMIZI_YA_AKO_NA_E.VIMILIKISHI', 'Uses the wrong noun-class form of the possessive (kitabu yangu for kitabu changu).', '{"question":"Jaza: Mbwa ___ (-ako) ni mkubwa.","wrong_answer":"yako","correct_answer":"wako"}'::jsonb, 'Town Kiswahili uses yangu, yako, yake for every noun; the child has not seen the ngeli agreement.', 'The question "Jaza: Mbwa ___ (-ako) ni mkubwa." with "yako" among the options.', 'Pair nouns and possessives by colour: kitabu changu, kiti chake, mtoto wangu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T5_MATUMIZI_YA_AKO_NA_E.VIMILIKISHI.M2_SAR_NUMPOSS_T5', 'KISW.G2.SARUFI.T5_MATUMIZI_YA_AKO_NA_E.VIMILIKISHI', 'Leaves the possessive singular with a plural noun (vitabu changu).', '{"question":"Jaza: Vikombe ___ (-ako) ni safi.","wrong_answer":"chako","correct_answer":"vyako"}'::jsonb, 'The child changes the noun and forgets the possessive.', 'The question "Jaza: Vikombe ___ (-ako) ni safi." with "chako" among the options.', 'Change one object to many in front of the child; both words change.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T5_MATUMIZI_YA_AKO_NA_E.VIMILIKISHI.M2_SAR_OWNER_T5', 'KISW.G2.SARUFI.T5_MATUMIZI_YA_AKO_NA_E.VIMILIKISHI', 'Uses the possessive of the wrong owner (-ake for something that is his own, -ake for many owners).', '{"question":"Mwalimu anawaambia wanafunzi wote: \"Leteni madaftari ___.\"","wrong_answer":"yako","correct_answer":"yenu"}'::jsonb, 'The child has not linked -angu, -ako, -ake, -etu, -enu, -ao to who owns the thing.', 'The question "Mwalimu anawaambia wanafunzi wote: "Leteni madaftari ___."" with "yako" among the options.', 'Hold up an object: Ni cha nani? Answer with the owner first, then the possessive.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T5_MATUMIZI_YA_AKO_NA_E.VIMILIKISHI.M2_SAR_ORDERPOSS_T5', 'KISW.G2.SARUFI.T5_MATUMIZI_YA_AKO_NA_E.VIMILIKISHI', 'Puts the possessive before the noun (yangu kalamu), in English word order.', '{"question":"Ni lipi sahihi?","wrong_answer":"wako paka","correct_answer":"paka wako"}'::jsonb, 'English puts "my" before the noun; Kiswahili puts it after.', 'The question "Ni lipi sahihi?" with "wako paka" among the options.', 'Build the phrase with cards: the noun first, then the possessive.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI.M2_SAU_NEAR_T6', 'KISW.G2.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'Says /n/ for /ny/, so "nyanya" becomes "nanya".', '{"question":"Mwalimu anasema \"nyanya\". Neno lipi limetamkwa vizuri?","wrong_answer":"nanya","correct_answer":"nyanya"}'::jsonb, 'Many Kenyan first languages have no /ny/, or do not separate it from /n/; the child puts in the home sound.', 'The question "Mwalimu anasema "nyanya". Neno lipi limetamkwa vizuri?" with "nanya" among the options.', 'Say the two side by side, slowly, watching the mouth; the child holds up a card for the sound he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI.M2_SAU_VOWEL_T6', 'KISW.G2.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'Pushes a vowel into the cluster, so "nyota" is said "niyota".', '{"question":"Tamka neno \"nyota\". Ni lipi sahihi?","wrong_answer":"niyota","correct_answer":"nyota"}'::jsonb, 'In the child''s first language, or in English loan habits, two consonants rarely sit together; he breaks them with a vowel.', 'The question "Tamka neno "nyota". Ni lipi sahihi?" with "niyota" among the options.', 'Say the cluster in one beat, then the word; clap once for the cluster syllable.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI.M2_SAU_DROP_T6', 'KISW.G2.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'Drops part of the target sound, so "ngoma" becomes "goma".', '{"question":"Neno \"ngoma\" limeandikwa au kutamkwa vipi kwa usahihi?","wrong_answer":"goma","correct_answer":"ngoma"}'::jsonb, 'The second part of the sound (the w or y glide, or the soft nasal) is quick and quiet; the child does not hear it and leaves it out.', 'The question "Neno "ngoma" limeandikwa au kutamkwa vipi kwa usahihi?" with "goma" among the options.', 'Stretch the syllable slowly (p-y-a), then say it fast; the child copies.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI.M2_SAU_SYLL_T6', 'KISW.G2.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'Splits "nyanya" by letters rather than by syllables (each Kiswahili syllable ends in a vowel).', '{"question":"Neno \"nyanya\" lina silabi zipi?","wrong_answer":"n-y-a-n-y-a","correct_answer":"nya-nya"}'::jsonb, 'The child has learnt letters one by one and has not been shown that a syllable is a sound that ends in a vowel.', 'The question "Neno "nyanya" lina silabi zipi?" with "n-y-a-n-y-a" among the options.', 'Clap the word: one clap per vowel; the consonants go with the vowel after them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI.M2_SAU_PICK_T6', 'KISW.G2.KUSIKI.T6_MATAMSHI_BORA.MATAMSHI', 'Picks a word with no target sound when asked for one that has it.', '{"question":"Ni neno lipi lina sauti /ny/, /ng/?","wrong_answer":"baba","correct_answer":"ngoma"}'::jsonb, 'The child looks at the first letter or the picture, not at the sound.', 'The question "Ni neno lipi lina sauti /ny/, /ng/?" with "baba" among the options.', 'Underline the target sound in each word on the card before choosing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_SOUND_T6', 'KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads the target word wrongly: "nyumba" as "numba".', '{"question":"Neno \"nyumba\" linasomwa vipi?","wrong_answer":"numba","correct_answer":"nyumba"}'::jsonb, 'The child reads the letters with the sounds of his first language, or adds a vowel to break the cluster.', 'The question "Neno "nyumba" linasomwa vipi?" with "numba" among the options.', 'Pick out the target words before reading; practise them on cards, then read the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_WORD_T6', 'KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Babu na bibi wanaishi kijijini.\"?","wrong_answer":"Babu ... na ... bibi ... wanaishi ... kijijini.","correct_answer":"Babu na bibi wanaishi kijijini."}'::jsonb, 'The child is still decoding each word; he has not yet read a group of words as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Babu na bibi wanaishi kijijini."?" with "Babu ... na ... bibi ... wanaishi ... kijijini." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it in one breath.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_QUIET_T6', 'KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads so softly (or so loudly, shouting) that the class cannot follow.', '{"question":"Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?","wrong_answer":"ya chini ili nisikosee mbele ya wenzangu","correct_answer":"ya kusikika na wote darasani, bila kupiga kelele"}'::jsonb, 'Shyness, or the belief that reading well means reading loud.', 'The question "Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?" with "ya chini ili nisikosee mbele ya wenzangu" among the options.', 'Stand the reader at the front and a listener at the back: the listener raises a hand when he hears every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_PACE_T6', 'KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Kasi ifaayo ya kusoma kifungu ni ipi?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, karibu maneno 39 kwa dakika"}'::jsonb, 'Reading races in class reward speed; nobody asked whether the listeners understood.', 'The question "Kasi ifaayo ya kusoma kifungu ni ipi?" with "haraka iwezekanavyo" among the options.', 'Time two readings, one very fast and one at speaking pace; the listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_MARK_T6', 'KISW.G2.KUSOMA.T6_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question in the flat voice of a statement and runs on through the koma and kikomo.', '{"question":"Sentensi \"Je, umemtembelea nyanya?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the marks.', 'The question "Sentensi "Je, umemtembelea nyanya?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that fits each reading; clap at each kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T6_TAHAJIA_IMLA.IMLA.M2_TAH_MT_T6', 'KISW.G2.KUANDI.T6_TAHAJIA_IMLA.IMLA', 'Spells the word with the sound of his first language: "shangazi" written "sangazi".', '{"question":"Ni tahajia ipi sahihi?","wrong_answer":"sangazi","correct_answer":"shangazi"}'::jsonb, 'The child writes as he says the word; if his first language merges the two sounds, the letter is a guess.', 'The question "Ni tahajia ipi sahihi?" with "sangazi" among the options.', 'Keep a list of the class''s hard pairs (l/r, s/sh, z/dh, s/th); say each word slowly before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T6_TAHAJIA_IMLA.IMLA.M2_TAH_NASAL_T6', 'KISW.G2.KUANDI.T6_TAHAJIA_IMLA.IMLA', 'Drops the nasal: "ndugu" written "dugu".', '{"question":"Ni tahajia ipi sahihi?","wrong_answer":"dugu","correct_answer":"ndugu"}'::jsonb, 'The n or m before a consonant is soft and quick; the child does not hear it.', 'The question "Ni tahajia ipi sahihi?" with "dugu" among the options.', 'Hum the nasal before the word (mmm-bwa, nnn-dege).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T6_TAHAJIA_IMLA.IMLA.M2_TAH_VOWEL_T6', 'KISW.G2.KUANDI.T6_TAHAJIA_IMLA.IMLA', 'Writes a long vowel short, so the word changes: "kaa" written "ka".', '{"question":"Andika neno lenye maana ya \"kuketi au kuishi mahali\".","wrong_answer":"ka","correct_answer":"kaa"}'::jsonb, 'The child hears the length but does not know it is shown by two letters.', 'The question "Andika neno lenye maana ya "kuketi au kuishi mahali"." with "ka" among the options.', 'Clap the two vowels as two beats; compare a word with one and two vowels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T6_TAHAJIA_IMLA.IMLA.M2_TAH_NGAPOS_T6', 'KISW.G2.KUANDI.T6_TAHAJIA_IMLA.IMLA', 'Writes ng'' without the apostrophe (ngombe for ng''ombe), or puts it where it does not belong (ng''oma for ngoma).', '{"question":"Ni tahajia ipi sahihi ya mnyama anayetupa maziwa?","wrong_answer":"ngombe","correct_answer":"ng''ombe"}'::jsonb, 'Ng'' and ng are two sounds; the apostrophe looks like dirt on the page to the child.', 'The question "Ni tahajia ipi sahihi ya mnyama anayetupa maziwa?" with "ngombe" among the options.', 'Say ng''ombe and ngoma: the first has no g sound; mark it with the apostrophe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T6_TAHAJIA_IMLA.IMLA.M2_TAH_JOIN_T6', 'KISW.G2.KUANDI.T6_TAHAJIA_IMLA.IMLA', 'Joins two words into one, or splits one word into two (kwasababu; mwana funzi).', '{"question":"Ni lipi sahihi?","wrong_answer":"Nilichelewa kwasababu ya mvua.","correct_answer":"Nilichelewa kwa sababu ya mvua."}'::jsonb, 'In speech the words run together; the child has not seen each written apart.', 'The question "Ni lipi sahihi?" with "Nilichelewa kwasababu ya mvua." among the options.', 'Count the words aloud with a finger for each before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T6_MATUMIZI_YA_REFU_KUB.VIVUMISHI.M2_SAR_CONCADJ_T6', 'KISW.G2.SARUFI.T6_MATUMIZI_YA_REFU_KUB.VIVUMISHI', 'Gives the adjective the people prefix whatever the noun (kiti mzuri).', '{"question":"Jaza: Kiti ___ (-kubwa).","wrong_answer":"mkubwa","correct_answer":"kikubwa"}'::jsonb, 'Mzuri is the form the child hears most (mtoto mzuri) and is used everywhere.', 'The question "Jaza: Kiti ___ (-kubwa)." with "mkubwa" among the options.', 'Match noun and adjective by colour: kiti kizuri, mtoto mzuri, vitu vizuri.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T6_MATUMIZI_YA_REFU_KUB.VIVUMISHI.M2_SAR_NADJ_T6', 'KISW.G2.SARUFI.T6_MATUMIZI_YA_REFU_KUB.VIVUMISHI', 'Gives an n-n noun the m- form of the adjective (nyumba mzuri for nyumba nzuri).', '{"question":"Jaza: Nyumba ___ (-refu).","wrong_answer":"mrefu","correct_answer":"ndefu"}'::jsonb, 'The n- prefix and its sound changes (nzuri, ndefu, nyeupe) are new to the child.', 'The question "Jaza: Nyumba ___ (-refu)." with "mrefu" among the options.', 'Read pairs aloud: nyumba nzuri, kalamu ndefu, nguo nyeupe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T6_MATUMIZI_YA_REFU_KUB.VIVUMISHI.M2_SAR_ORDERADJ_T6', 'KISW.G2.SARUFI.T6_MATUMIZI_YA_REFU_KUB.VIVUMISHI', 'Puts the adjective before the noun (mzuri mtoto), in English word order.', '{"question":"Ni lipi sahihi?","wrong_answer":"mrefu babu","correct_answer":"babu mrefu"}'::jsonb, 'English puts the describing word first.', 'The question "Ni lipi sahihi?" with "mrefu babu" among the options.', 'Build with cards: noun first, then the adjective.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T6_MATUMIZI_YA_REFU_KUB.VIVUMISHI.M2_SAR_PLADJ_T6', 'KISW.G2.SARUFI.T6_MATUMIZI_YA_REFU_KUB.VIVUMISHI', 'Leaves the adjective singular with a plural noun (watoto mzuri).', '{"question":"Jaza: Wajomba ___ (-refu).","wrong_answer":"mrefu","correct_answer":"warefu"}'::jsonb, 'The child changes the noun only.', 'The question "Jaza: Wajomba ___ (-refu)." with "mrefu" among the options.', 'Change the noun to many and ask the child to change every word that goes with it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T6_MATUMIZI_YA_REFU_KUB.VIVUMISHI.M2_SAR_OPPADJ_T6', 'KISW.G2.SARUFI.T6_MATUMIZI_YA_REFU_KUB.VIVUMISHI', 'Picks the opposite member of the pair (mrefu for a short person).', '{"question":"Picha inaonyesha mti mfupi. Mti ni ___.","wrong_answer":"mrefu","correct_answer":"mfupi"}'::jsonb, 'The pair is learnt together and the two words are swapped.', 'The question "Picha inaonyesha mti mfupi. Mti ni ___." with "mrefu" among the options.', 'Act the pairs with the body: stretch for refu, crouch for fupi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T7_MAAGIZO.MAAGIZO.M2_MAG_HALF_T7', 'KISW.G2.KUSIKI.T7_MAAGIZO.MAAGIZO', 'Carries out only the first part of a two-step instruction.', '{"question":"Agizo: \"Panga viti, kisha ufagie sebule.\" Umefanya nini?","wrong_answer":"anapanga viti tu","correct_answer":"anapanga viti kisha anafagia sebule"}'::jsonb, 'The child starts acting as soon as he hears the first verb and stops listening.', 'The question "Agizo: "Panga viti, kisha ufagie sebule." Umefanya nini?" with "anapanga viti tu" among the options.', 'Hold up one finger for each step while giving the instruction; the child repeats the steps before moving.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T7_MAAGIZO.MAAGIZO.M2_MAG_ORDER_T7', 'KISW.G2.KUSIKI.T7_MAAGIZO.MAAGIZO', 'Does the steps in the wrong order.', '{"question":"Agizo: \"Osha mikono, kisha ule chakula.\" Ni nini kinatangulia?","wrong_answer":"kula chakula","correct_answer":"kuosha mikono"}'::jsonb, 'The child does the step he wants most first; the order words kwanza and kisha are not yet noticed.', 'The question "Agizo: "Osha mikono, kisha ule chakula." Ni nini kinatangulia?" with "kula chakula" among the options.', 'Number the steps on the board with kwanza, kisha, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T7_MAAGIZO.MAAGIZO.M2_MAG_DIR_T7', 'KISW.G2.KUSIKI.T7_MAAGIZO.MAAGIZO', 'Mixes a direction or action word.', '{"question":"Agizo: \"Weka kikombe juu ya meza.\" Ni kitendo kipi sahihi?","wrong_answer":"anakiweka chini ya meza","correct_answer":"anakiweka juu ya meza"}'::jsonb, 'Pairs such as kulia/kushoto and juu/chini are learnt together and swapped.', 'The question "Agizo: "Weka kikombe juu ya meza." Ni kitendo kipi sahihi?" with "anakiweka chini ya meza" among the options.', 'Play "Mwalimu anasema": the teacher calls the word, the child acts it; mark the right hand with a band.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T7_MAAGIZO.MAAGIZO.M2_MAG_VAGUE_T7', 'KISW.G2.KUSIKI.T7_MAAGIZO.MAAGIZO', 'Gives an instruction that leaves out what to act on, or with no polite word (Lete!).', '{"question":"Ni agizo lipi liko wazi na lina adabu?","wrong_answer":"Lete!","correct_answer":"Tafadhali lete kitabu chako mezani."}'::jsonb, 'The child knows what he means and does not see that the listener cannot.', 'The question "Ni agizo lipi liko wazi na lina adabu?" with "Lete!" among the options.', 'The child gives the instruction to a partner, who does exactly what was said and no more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T7_KUSOMA_KWA_UFAHAMU_K.UFAHAMU.M2_UFM_WORD_T7', 'KISW.G2.KUSOMA.T7_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'Gives "sakafu" the meaning of a word that looks or sounds like it.', '{"question":"Soma: \"Sebuleni kwetu kuna viti vinne, meza na runinga. Kila Jumamosi, mimi na dada yangu hupangusa vumbi na kufagia sakafu. Sebule huwa safi na nadhifu.\" Neno \"sakafu\" lina maana gani?","wrong_answer":"safari","correct_answer":"sehemu ya chini ya chumba tunayoikanyaga"}'::jsonb, 'The child matches the word to a known one by its look instead of reading the sentence around it.', 'The question "Soma: "Sebuleni kwetu kuna viti vinne, meza na runinga. Kila Jumamosi, mimi na dada yangu hupangusa vumbi na kufagia sakafu. Sebule huwa safi na nadhifu." Neno "sakafu" lina maana gani?" with "safari" among the options.', 'Cover the word; the child says what word would fit the sentence, then uncovers it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T7_KUSOMA_KWA_UFAHAMU_K.UFAHAMU.M2_UFM_MSG_T7', 'KISW.G2.KUSOMA.T7_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'Gives one detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ni upi?","wrong_answer":"Kuna viti vinne.","correct_answer":"Tushirikiane kuweka nyumba yetu safi."}'::jsonb, 'The detail is what the child remembers best; he has not been asked what the writer wants us to know.', 'The question "Ujumbe wa kifungu ni upi?" with "Kuna viti vinne." among the options.', 'Ask two questions side by side: "Nini kilitokea?" and "Kifungu kinatuambia nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T7_KUSOMA_KWA_UFAHAMU_K.UFAHAMU.M2_UFM_GUESS_T7', 'KISW.G2.KUSOMA.T7_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'Predicts something the passage gives no clue for, without looking at the picture.', '{"question":"Picha inaonyesha wageni wakibisha mlango. Watoto watafanya nini?","wrong_answer":"Watajificha.","correct_answer":"Watawakaribisha wageni sebuleni."}'::jsonb, 'Prediction is taken as free imagination; the child has not been shown that clues in the text and picture point the way.', 'The question "Picha inaonyesha wageni wakibisha mlango. Watoto watafanya nini?" with "Watajificha." among the options.', 'Underline the clue words and point at the picture; the guess must fit them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T7_KUSOMA_KWA_UFAHAMU_K.UFAHAMU.M2_UFM_LESSON_T7', 'KISW.G2.KUSOMA.T7_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'Retells what happened when asked for the lesson.', '{"question":"Tunajifunza nini kutokana na kifungu?","wrong_answer":"Kuna runinga sebuleni.","correct_answer":"Tunapaswa kusaidia kazi za nyumbani."}'::jsonb, 'The lesson question sounds like a what-happened question to the child.', 'The question "Tunajifunza nini kutokana na kifungu?" with "Kuna runinga sebuleni." among the options.', 'Start the answer with "Tunajifunza kwamba tunapaswa..."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T7_KUSOMA_KWA_UFAHAMU_K.UFAHAMU.M2_UFM_OWN_T7', 'KISW.G2.KUSOMA.T7_KUSOMA_KWA_UFAHAMU_K.UFAHAMU', 'Answers from his own life instead of from the passage.', '{"question":"Watoto husafisha sebule siku gani?","wrong_answer":"Sisi husafisha Jumapili.","correct_answer":"Jumamosi"}'::jsonb, 'The child links the question to what he knows from home and does not check the text.', 'The question "Watoto husafisha sebule siku gani?" with "Sisi husafisha Jumapili." among the options.', 'Ask the child to point at the line in the passage that gives the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T7_UHARIRI.UHARIRI.M2_HAR_NEAT_T7', 'KISW.G2.KUANDI.T7_UHARIRI.UHARIRI', 'Thinks editing means copying the same writing more neatly, mistakes and all.', '{"question":"Kuhariri ni nini?","wrong_answer":"kuandika upya kwa mwandiko mzuri","correct_answer":"kusoma maandishi na kusahihisha makosa"}'::jsonb, 'The child has seen clean copies praised and thinks neatness is the whole job.', 'The question "Kuhariri ni nini?" with "kuandika upya kwa mwandiko mzuri" among the options.', 'Give a short passage with three planted mistakes; the child finds them before copying.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T7_UHARIRI.UHARIRI.M2_HAR_NOREAD_T7', 'KISW.G2.KUANDI.T7_UHARIRI.UHARIRI', 'Does not read his writing back, so a missing word stays missing.', '{"question":"Sahihisha: Mama alipika chakula kitamu sana sana.","wrong_answer":"Mama alipika chakula kitamu sana sana.","correct_answer":"Mama alipika chakula kitamu sana."}'::jsonb, 'The child knows what he meant and his eye fills the gap or skips the repeat.', 'The question "Sahihisha: Mama alipika chakula kitamu sana sana." with "Mama alipika chakula kitamu sana sana." among the options.', 'Read it aloud with a finger under each word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T7_UHARIRI.UHARIRI.M2_HAR_CAPSTOP_T7', 'KISW.G2.KUANDI.T7_UHARIRI.UHARIRI', 'Checks spelling only and leaves out the capital and the kikomo.', '{"question":"Hariri: tuliketi sebuleni","wrong_answer":"tuliketi sebuleni","correct_answer":"Tuliketi sebuleni."}'::jsonb, 'Spelling is what the teacher marks most, so it is all the child looks for.', 'The question "Hariri: tuliketi sebuleni" with "tuliketi sebuleni" among the options.', 'An editing card: Herufi kubwa? Kikomo? Neno limekosekana? Tahajia?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T7_UHARIRI.UHARIRI.M2_HAR_HOLE_T7', 'KISW.G2.KUANDI.T7_UHARIRI.UHARIRI', 'Rubs out so hard the page tears, or scribbles over the error so it cannot be read.', '{"question":"Ukipata kosa, unafanya nini?","wrong_answer":"ninalifuta kwa nguvu au kulichora juu","correct_answer":"ninapiga mstari mmoja juu yake na kuandika sahihi"}'::jsonb, 'The child fears a mistake showing.', 'The question "Ukipata kosa, unafanya nini?" with "ninalifuta kwa nguvu au kulichora juu" among the options.', 'Show one neat line through the error and the right word above it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T7_UKANUSHO_WA_NAFSI_YA.UKANUSHAJI.M2_SAR_FINALA_T7', 'KISW.G2.SARUFI.T7_UKANUSHO_WA_NAFSI_YA.UKANUSHAJI', 'Keeps the final -a in the negative present (hasoma for hasomi).', '{"question":"Kanusha: Wewe unasoma.","wrong_answer":"Wewe husoma.","correct_answer":"Wewe husomi."}'::jsonb, 'The child adds the negative prefix and leaves the rest of the verb as it was.', 'The question "Kanusha: Wewe unasoma." with "Wewe husoma." among the options.', 'Show the pair with the end of the verb circled: anasoma - hasomi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T7_UKANUSHO_WA_NAFSI_YA.UKANUSHAJI.M2_SAR_KEEPNA_T7', 'KISW.G2.SARUFI.T7_UKANUSHO_WA_NAFSI_YA.UKANUSHAJI', 'Keeps the tense marker -na- in the negative (hanasomi for hasomi).', '{"question":"Kanusha: Wewe unapika.","wrong_answer":"Wewe hunapiki.","correct_answer":"Wewe hupiki."}'::jsonb, 'The child negates by adding ha- to the whole positive verb.', 'The question "Kanusha: Wewe unapika." with "Wewe hunapiki." among the options.', 'Cross out na in the positive form and change the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T7_UKANUSHO_WA_NAFSI_YA.UKANUSHAJI.M2_SAR_SIPLUS_T7', 'KISW.G2.SARUFI.T7_UKANUSHO_WA_NAFSI_YA.UKANUSHAJI', 'Negates by putting si before the positive verb (Yeye si anasoma).', '{"question":"Kanusha: Nyinyi mnasoma.","wrong_answer":"Nyinyi si mnasoma.","correct_answer":"Nyinyi hamsomi."}'::jsonb, 'Si is the negative the child knows (si mimi), so he puts it in front of any sentence.', 'The question "Kanusha: Nyinyi mnasoma." with "Nyinyi si mnasoma." among the options.', 'Show si as the negative of ni (Yeye si mwalimu) and ha- as the negative of a verb.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T7_UKANUSHO_WA_NAFSI_YA.UKANUSHAJI.M2_SAR_PERSNEG_T7', 'KISW.G2.SARUFI.T7_UKANUSHO_WA_NAFSI_YA.UKANUSHAJI', 'Uses the negative prefix of another person (Wao hasomi for hawasomi; Mimi hasomi for sisomi).', '{"question":"Kanusha: Nyinyi mnacheza.","wrong_answer":"Nyinyi hawachezi.","correct_answer":"Nyinyi hamchezi."}'::jsonb, 'The child learnt one negative form (ha-) and uses it for all persons.', 'The question "Kanusha: Nyinyi mnacheza." with "Nyinyi hawachezi." among the options.', 'Table of persons: si-, hu-, ha-, hatu-, ham-, hawa-; the child points before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI.M2_SAU_NEAR_T8', 'KISW.G2.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'Says /g/ for /gh/, so "ghafla" becomes "gafla".', '{"question":"Mwalimu anasema \"ghafla\". Neno lipi limetamkwa vizuri?","wrong_answer":"gafla","correct_answer":"ghafla"}'::jsonb, 'Many Kenyan first languages have no /gh/, or do not separate it from /g/; the child puts in the home sound.', 'The question "Mwalimu anasema "ghafla". Neno lipi limetamkwa vizuri?" with "gafla" among the options.', 'Say the two side by side, slowly, watching the mouth; the child holds up a card for the sound he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI.M2_SAU_NEAR2_T8', 'KISW.G2.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'Says /ng/ for /ng''/, so "ng''ombe" becomes "ngombe".', '{"question":"Neno lipi limetamkwa vizuri?","wrong_answer":"ngombe","correct_answer":"ng''ombe"}'::jsonb, '/ng''/ and /ng/ are close; a first language with only one of them puts that one in both places.', 'The question "Neno lipi limetamkwa vizuri?" with "ngombe" among the options.', 'Contrast the two with a mirror and a hand before the mouth; the child says which he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI.M2_SAU_SYLL_T8', 'KISW.G2.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'Splits "ghafla" by letters rather than by syllables (each Kiswahili syllable ends in a vowel).', '{"question":"Neno \"ghafla\" lina silabi zipi?","wrong_answer":"g-h-a-f-l-a","correct_answer":"gha-fla"}'::jsonb, 'The child has learnt letters one by one and has not been shown that a syllable is a sound that ends in a vowel.', 'The question "Neno "ghafla" lina silabi zipi?" with "g-h-a-f-l-a" among the options.', 'Clap the word: one clap per vowel; the consonants go with the vowel after them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI.M2_SAU_PICK_T8', 'KISW.G2.KUSIKI.T8_MATAMSHI_BORA.MATAMSHI', 'Picks a word with no target sound when asked for one that has it.', '{"question":"Ni neno lipi lina sauti /gh/, /ng''/?","wrong_answer":"taa","correct_answer":"ng''ombe"}'::jsonb, 'The child looks at the first letter or the picture, not at the sound.', 'The question "Ni neno lipi lina sauti /gh/, /ng''/?" with "taa" among the options.', 'Underline the target sound in each word on the card before choosing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_SOUND_T8', 'KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads the target word wrongly: "ng''ambo" as "ngambo".', '{"question":"Neno \"ng''ambo\" linasomwa vipi?","wrong_answer":"ngambo","correct_answer":"ng''ambo"}'::jsonb, 'The child reads the letters with the sounds of his first language, or adds a vowel to break the cluster.', 'The question "Neno "ng''ambo" linasomwa vipi?" with "ngambo" among the options.', 'Pick out the target words before reading; practise them on cards, then read the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_WORD_T8', 'KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Tunavuka barabara kwa uangalifu.\"?","wrong_answer":"Tunavuka ... barabara ... kwa ... uangalifu.","correct_answer":"Tunavuka barabara kwa uangalifu."}'::jsonb, 'The child is still decoding each word; he has not yet read a group of words as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Tunavuka barabara kwa uangalifu."?" with "Tunavuka ... barabara ... kwa ... uangalifu." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it in one breath.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_QUIET_T8', 'KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads so softly (or so loudly, shouting) that the class cannot follow.', '{"question":"Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?","wrong_answer":"ya chini ili nisikosee mbele ya wenzangu","correct_answer":"ya kusikika na wote darasani, bila kupiga kelele"}'::jsonb, 'Shyness, or the belief that reading well means reading loud.', 'The question "Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?" with "ya chini ili nisikosee mbele ya wenzangu" among the options.', 'Stand the reader at the front and a listener at the back: the listener raises a hand when he hears every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_PACE_T8', 'KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Kasi ifaayo ya kusoma kifungu ni ipi?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, karibu maneno 42 kwa dakika"}'::jsonb, 'Reading races in class reward speed; nobody asked whether the listeners understood.', 'The question "Kasi ifaayo ya kusoma kifungu ni ipi?" with "haraka iwezekanavyo" among the options.', 'Time two readings, one very fast and one at speaking pace; the listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_MARK_T8', 'KISW.G2.KUSOMA.T8_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question in the flat voice of a statement and runs on through the koma and kikomo.', '{"question":"Sentensi \"Je, umeangalia kulia na kushoto?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the marks.', 'The question "Sentensi "Je, umeangalia kulia na kushoto?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that fits each reading; clap at each kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T8_TAHAJIA.TAHAJIA.M2_TAH_MT_T8', 'KISW.G2.KUANDI.T8_TAHAJIA.TAHAJIA', 'Spells the word with the sound of his first language: "barabara" written "balabala".', '{"question":"Ni tahajia ipi sahihi?","wrong_answer":"balabala","correct_answer":"barabara"}'::jsonb, 'The child writes as he says the word; if his first language merges the two sounds, the letter is a guess.', 'The question "Ni tahajia ipi sahihi?" with "balabala" among the options.', 'Keep a list of the class''s hard pairs (l/r, s/sh, z/dh, s/th); say each word slowly before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T8_TAHAJIA.TAHAJIA.M2_TAH_NASAL_T8', 'KISW.G2.KUANDI.T8_TAHAJIA.TAHAJIA', 'Drops the nasal: "mbele" written "bele".', '{"question":"Ni tahajia ipi sahihi?","wrong_answer":"bele","correct_answer":"mbele"}'::jsonb, 'The n or m before a consonant is soft and quick; the child does not hear it.', 'The question "Ni tahajia ipi sahihi?" with "bele" among the options.', 'Hum the nasal before the word (mmm-bwa, nnn-dege).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T8_TAHAJIA.TAHAJIA.M2_TAH_VOWEL_T8', 'KISW.G2.KUANDI.T8_TAHAJIA.TAHAJIA', 'Writes a long vowel short, so the word changes: "taa" written "ta".', '{"question":"Andika neno lenye maana ya \"kifaa cha kutoa mwanga\".","wrong_answer":"ta","correct_answer":"taa"}'::jsonb, 'The child hears the length but does not know it is shown by two letters.', 'The question "Andika neno lenye maana ya "kifaa cha kutoa mwanga"." with "ta" among the options.', 'Clap the two vowels as two beats; compare a word with one and two vowels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T8_TAHAJIA.TAHAJIA.M2_TAH_NGAPOS_T8', 'KISW.G2.KUANDI.T8_TAHAJIA.TAHAJIA', 'Writes ng'' without the apostrophe (ngombe for ng''ombe), or puts it where it does not belong (ng''oma for ngoma).', '{"question":"Ni tahajia ipi sahihi ya mnyama anayetupa maziwa?","wrong_answer":"ngombe","correct_answer":"ng''ombe"}'::jsonb, 'Ng'' and ng are two sounds; the apostrophe looks like dirt on the page to the child.', 'The question "Ni tahajia ipi sahihi ya mnyama anayetupa maziwa?" with "ngombe" among the options.', 'Say ng''ombe and ngoma: the first has no g sound; mark it with the apostrophe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T8_TAHAJIA.TAHAJIA.M2_TAH_JOIN_T8', 'KISW.G2.KUANDI.T8_TAHAJIA.TAHAJIA', 'Joins two words into one, or splits one word into two (kwasababu; mwana funzi).', '{"question":"Ni lipi sahihi?","wrong_answer":"Nilichelewa kwasababu ya mvua.","correct_answer":"Nilichelewa kwa sababu ya mvua."}'::jsonb, 'In speech the words run together; the child has not seen each written apart.', 'The question "Ni lipi sahihi?" with "Nilichelewa kwasababu ya mvua." among the options.', 'Count the words aloud with a finger for each before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T8_MATUMIZI_YA_HUU_NA_H.VIONYESHI.M2_SAR_CLASSDEM_T8', 'KISW.G2.SARUFI.T8_MATUMIZI_YA_HUU_NA_H.VIONYESHI', 'Uses the people word (huyu, yule) for a thing (kiti huyu).', '{"question":"Jaza: Mlango ___ ni mpana.","wrong_answer":"huyu","correct_answer":"huu"}'::jsonb, 'Huyu was the first pointing word learnt; the child uses it for anything.', 'The question "Jaza: Mlango ___ ni mpana." with "huyu" among the options.', 'Point at a child (huyu) and at a chair (hiki); then sort pictures by the pointing word they take.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T8_MATUMIZI_YA_HUU_NA_H.VIONYESHI.M2_SAR_NUMDEM_T8', 'KISW.G2.SARUFI.T8_MATUMIZI_YA_HUU_NA_H.VIONYESHI', 'Uses the one-thing pointing word with a plural noun (watoto huyu).', '{"question":"Jaza: Milango ___ imefungwa.","wrong_answer":"huu","correct_answer":"hii"}'::jsonb, 'The child changes the noun but not the pointing word.', 'The question "Jaza: Milango ___ imefungwa." with "huu" among the options.', 'Pair the forms on cards: huyu-hawa, yule-wale, hiki-hivi, hili-haya.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T8_MATUMIZI_YA_HUU_NA_H.VIONYESHI.M2_SAR_HII_T8', 'KISW.G2.SARUFI.T8_MATUMIZI_YA_HUU_NA_H.VIONYESHI', 'Uses hii for every noun (kitabu hii, mtoto hii), as in town Kiswahili.', '{"question":"Jaza: Mkono ___ umeumia.","wrong_answer":"hii","correct_answer":"huu"}'::jsonb, 'Hii is the pointing word heard most in town speech, where the noun class is dropped.', 'The question "Jaza: Mkono ___ umeumia." with "hii" among the options.', 'Read pairs aloud: kitabu hiki, mtoto huyu, nyumba hii; the child hears the match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T8_MATUMIZI_YA_HUU_NA_H.VIONYESHI.M2_SAR_DIST_T8', 'KISW.G2.SARUFI.T8_MATUMIZI_YA_HUU_NA_H.VIONYESHI', 'Mixes near and far pointing words (huyu for someone far away; yule for someone close).', '{"question":"Mti uko mbali kule. Unasema: Mti ___ ni mrefu.","wrong_answer":"huu","correct_answer":"ule"}'::jsonb, 'The child has not linked the forms to distance from the speaker.', 'The question "Mti uko mbali kule. Unasema: Mti ___ ni mrefu." with "huu" among the options.', 'Stand near one child and far from another; point and say huyu and yule; then swap places.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T9_MAZUNGUMZO_YA_PAPO_K.MAZUNGUMZO.M2_MAZ_TOPIC_T9', 'KISW.G2.KUSIKI.T9_MAZUNGUMZO_YA_PAPO_K.MAZUNGUMZO', 'Says something that has nothing to do with the topic.', '{"question":"Mnazungumza kuhusu kumtembelea daktari. Ni sentensi ipi inafaa?","wrong_answer":"Jana nilitazama katuni nzuri.","correct_answer":"Daktari alinidunga sindano."}'::jsonb, 'The child says what is on his mind; he has not learnt that a conversation has a topic everyone keeps to.', 'The question "Mnazungumza kuhusu kumtembelea daktari. Ni sentensi ipi inafaa?" with "Jana nilitazama katuni nzuri." among the options.', 'Put the topic picture in the middle; before speaking the child points to it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T9_MAZUNGUMZO_YA_PAPO_K.MAZUNGUMZO.M2_MAZ_TURN_T9', 'KISW.G2.KUSIKI.T9_MAZUNGUMZO_YA_PAPO_K.MAZUNGUMZO', 'Talks over others and does not wait for his turn.', '{"question":"Mwenzako anazungumza. Unafanya nini?","wrong_answer":"ninaanza kuzungumza pia","correct_answer":"ninasikiliza mpaka amalize, kisha ninazungumza"}'::jsonb, 'Eagerness: the child fears he will forget his idea.', 'The question "Mwenzako anazungumza. Unafanya nini?" with "ninaanza kuzungumza pia" among the options.', 'Pass a talking object (a ball): only the one holding it speaks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T9_MAZUNGUMZO_YA_PAPO_K.MAZUNGUMZO.M2_MAZ_MIX_T9', 'KISW.G2.KUSIKI.T9_MAZUNGUMZO_YA_PAPO_K.MAZUNGUMZO', 'Mixes English or Sheng words into the Kiswahili sentence.', '{"question":"Sema kwa Kiswahili sanifu:","wrong_answer":"Daktari alinipa injection.","correct_answer":"Daktari alinidunga sindano."}'::jsonb, 'At home and in town the child hears mixed speech and does not know the Kiswahili word.', 'The question "Sema kwa Kiswahili sanifu:" with "Daktari alinipa injection." among the options.', 'Keep a word wall: the English or Sheng word, and its Kiswahili word next to it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T9_MAZUNGUMZO_YA_PAPO_K.MAZUNGUMZO.M2_MAZ_GEST_T9', 'KISW.G2.KUSIKI.T9_MAZUNGUMZO_YA_PAPO_K.MAZUNGUMZO', 'Uses a gesture or face that does not match the words (smiling while giving sad news).', '{"question":"Unasema \"Rafiki yangu ni mgonjwa.\" Uso wako unaonyesha nini?","wrong_answer":"tabasamu kubwa","correct_answer":"huzuni"}'::jsonb, 'The child smiles from shyness or does not link the face to the message.', 'The question "Unasema "Rafiki yangu ni mgonjwa." Uso wako unaonyesha nini?" with "tabasamu kubwa" among the options.', 'Say one sentence with three faces; the class picks the face that fits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T9_MAZUNGUMZO_YA_PAPO_K.MAZUNGUMZO.M2_MAZ_LR_T9', 'KISW.G2.KUSIKI.T9_MAZUNGUMZO_YA_PAPO_K.MAZUNGUMZO', 'Says /l/ for /r/ (or /r/ for /l/) while speaking: "rafiki" becomes "lafiki".', '{"question":"Tamka vizuri: rafiki","wrong_answer":"lafiki","correct_answer":"rafiki"}'::jsonb, 'Several Kenyan first languages do not separate /l/ and /r/; the home sound carries into Kiswahili.', 'The question "Tamka vizuri: rafiki" with "lafiki" among the options.', 'Practise the pairs with a mirror: the tongue taps for r, it rests for l.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU.M2_UFM_WORD_T9', 'KISW.G2.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives "homa" the meaning of a word that looks or sounds like it.', '{"question":"Soma: \"Amina alikuwa na homa. Mama alimpeleka hospitalini. Daktari alimpima na kumpa dawa. Baada ya siku tatu, Amina alipona.\" Neno \"homa\" lina maana gani?","wrong_answer":"hema","correct_answer":"ugonjwa wa mwili kuwa na joto jingi"}'::jsonb, 'The child matches the word to a known one by its look instead of reading the sentence around it.', 'The question "Soma: "Amina alikuwa na homa. Mama alimpeleka hospitalini. Daktari alimpima na kumpa dawa. Baada ya siku tatu, Amina alipona." Neno "homa" lina maana gani?" with "hema" among the options.', 'Cover the word; the child says what word would fit the sentence, then uncovers it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU.M2_UFM_MSG_T9', 'KISW.G2.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Gives one detail of the passage as its message.', '{"question":"Ujumbe wa kifungu ni upi?","wrong_answer":"Amina alienda hospitalini.","correct_answer":"Tukiugua twende hospitalini mapema tupate matibabu."}'::jsonb, 'The detail is what the child remembers best; he has not been asked what the writer wants us to know.', 'The question "Ujumbe wa kifungu ni upi?" with "Amina alienda hospitalini." among the options.', 'Ask two questions side by side: "Nini kilitokea?" and "Kifungu kinatuambia nini?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU.M2_UFM_GUESS_T9', 'KISW.G2.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Predicts something the passage gives no clue for, without looking at the picture.', '{"question":"Picha inaonyesha Amina akibeba begi la shule asubuhi. Atafanya nini?","wrong_answer":"Atarudi hospitalini.","correct_answer":"Atarudi shuleni."}'::jsonb, 'Prediction is taken as free imagination; the child has not been shown that clues in the text and picture point the way.', 'The question "Picha inaonyesha Amina akibeba begi la shule asubuhi. Atafanya nini?" with "Atarudi hospitalini." among the options.', 'Underline the clue words and point at the picture; the guess must fit them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU.M2_UFM_LESSON_T9', 'KISW.G2.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Retells what happened when asked for the lesson.', '{"question":"Tunajifunza nini kutokana na kifungu?","wrong_answer":"Daktari alimpima Amina.","correct_answer":"Tunapaswa kumeza dawa kama daktari anavyoagiza."}'::jsonb, 'The lesson question sounds like a what-happened question to the child.', 'The question "Tunajifunza nini kutokana na kifungu?" with "Daktari alimpima Amina." among the options.', 'Start the answer with "Tunajifunza kwamba tunapaswa..."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU.M2_UFM_OWN_T9', 'KISW.G2.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.UFAHAMU', 'Answers from his own life instead of from the passage.', '{"question":"Amina alipona baada ya siku ngapi?","wrong_answer":"Mimi nilipona baada ya wiki moja.","correct_answer":"siku tatu"}'::jsonb, 'The child links the question to what he knows from home and does not check the text.', 'The question "Amina alipona baada ya siku ngapi?" with "Mimi nilipona baada ya wiki moja." among the options.', 'Ask the child to point at the line in the passage that gives the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T9_KUANDIKA_KIFUNGU.KIFUNGU.M2_INS_NAME_T9', 'KISW.G2.KUANDI.T9_KUANDIKA_KIFUNGU.KIFUNGU', 'Lists the things in the picture (mti, mtoto, mbwa) instead of writing sentences about what is happening.', '{"question":"Ni kipi ni kifungu kuhusu picha?","wrong_answer":"mti. mtoto. mbwa.","correct_answer":"Mtoto anacheza na mbwa chini ya mti."}'::jsonb, 'Naming pictures was the earlier task; the child has not moved to sentences.', 'The question "Ni kipi ni kifungu kuhusu picha?" with "mti. mtoto. mbwa." among the options.', 'Ask "Nani? Anafanya nini? Wapi?" for each part of the picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T9_KUANDIKA_KIFUNGU.KIFUNGU.M2_INS_TITLE_T9', 'KISW.G2.KUANDI.T9_KUANDIKA_KIFUNGU.KIFUNGU', 'Writes no title, or a title that does not fit the writing.', '{"question":"Kichwa kipi kinafaa insha kuhusu hospitalini?","wrong_answer":"Insha","correct_answer":"Hospitali Yetu"}'::jsonb, 'The child thinks the word "insha" or the date is the title.', 'The question "Kichwa kipi kinafaa insha kuhusu hospitalini?" with "Insha" among the options.', 'Read the finished writing and ask: what is it about in three words?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T9_KUANDIKA_KIFUNGU.KIFUNGU.M2_INS_HALAFU_T9', 'KISW.G2.KUANDI.T9_KUANDIKA_KIFUNGU.KIFUNGU', 'Joins every sentence with "na halafu", so the writing is one long sentence.', '{"question":"Ni lipi limeandikwa vizuri?","wrong_answer":"Tuliamka na halafu tukaoga na halafu tukaenda sokoni.","correct_answer":"Tuliamka asubuhi. Tulioga, kisha tukaenda sokoni."}'::jsonb, 'Spoken retelling joins events with na halafu; the child writes as he talks.', 'The question "Ni lipi limeandikwa vizuri?" with "Tuliamka na halafu tukaoga na halafu tukaenda sokoni." among the options.', 'Give a word bank: kwanza, kisha, baadaye, mwishowe; one per sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T9_KUANDIKA_KIFUNGU.KIFUNGU.M2_INS_TENSE_T9', 'KISW.G2.KUANDI.T9_KUANDIKA_KIFUNGU.KIFUNGU', 'Slips from one tense to another in the middle of the writing (past -li- to present -na-, or habitual hu- to past).', '{"question":"Ni lipi sahihi?","wrong_answer":"Jana nilienda hospitalini. Daktari ananipima.","correct_answer":"Jana nilienda hospitalini. Daktari alinipima."}'::jsonb, 'The child thinks of the events as he writes and the tense of the moment comes in.', 'The question "Ni lipi sahihi?" with "Jana nilienda hospitalini. Daktari ananipima." among the options.', 'Underline every verb; all the tense markers should match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T9_KUANDIKA_KIFUNGU.KIFUNGU.M2_INS_MIX_T9', 'KISW.G2.KUANDI.T9_KUANDIKA_KIFUNGU.KIFUNGU', 'Puts English or Sheng words into the Kiswahili writing.', '{"question":"Sahihisha:","wrong_answer":"Daktari alinipa tablets.","correct_answer":"Daktari alinipa vidonge."}'::jsonb, 'The child does not know the Kiswahili word and fills the gap with the one he knows.', 'The question "Sahihisha:" with "Daktari alinipa tablets." among the options.', 'Keep a word bank of theme words on the board before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T9_MATUMIZI_YA_VIZURI_N.VIELEZI.M2_SAR_ADVADJ_T9', 'KISW.G2.SARUFI.T9_MATUMIZI_YA_VIZURI_N.VIELEZI', 'Uses the adjective form for how something is done (anaimba mzuri for anaimba vizuri).', '{"question":"Jaza: Muuguzi anaimba ___ (-zuri).","wrong_answer":"mzuri","correct_answer":"vizuri"}'::jsonb, 'Mzuri is the form the child knows best and he uses it for actions too.', 'The question "Jaza: Muuguzi anaimba ___ (-zuri)." with "mzuri" among the options.', 'Ask "Anaimbaje?" (how) and "Ni mtoto wa namna gani?" (what kind); the first takes vizuri, the second mzuri.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T9_MATUMIZI_YA_VIZURI_N.VIELEZI.M2_SAR_ADVOPP_T9', 'KISW.G2.SARUFI.T9_MATUMIZI_YA_VIZURI_N.VIELEZI', 'Picks the opposite word of the pair (polepole for haraka, vizuri for vibaya).', '{"question":"Mgonjwa ana maumivu, anatembea taratibu. Anatembea ___.","wrong_answer":"haraka","correct_answer":"polepole"}'::jsonb, 'The pairs are learnt together and swapped.', 'The question "Mgonjwa ana maumivu, anatembea taratibu. Anatembea ___." with "haraka" among the options.', 'Act the pairs: walk polepole, then haraka; the child names each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T9_MATUMIZI_YA_VIZURI_N.VIELEZI.M2_SAR_ADVKI_T9', 'KISW.G2.SARUFI.T9_MATUMIZI_YA_VIZURI_N.VIELEZI', 'Writes the manner word with ki- (kizuri) instead of vi- (vizuri).', '{"question":"Jaza: Daktari alimtibu ___ (-zuri).","wrong_answer":"kizuri","correct_answer":"vizuri"}'::jsonb, 'Ki-/vi- are heard as one family and the child picks the wrong member.', 'The question "Jaza: Daktari alimtibu ___ (-zuri)." with "kizuri" among the options.', 'Show that vizuri and vibaya always start with vi- when they tell how something is done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T9_MATUMIZI_YA_VIZURI_N.VIELEZI.M2_SAR_ADVTHING_T9', 'KISW.G2.SARUFI.T9_MATUMIZI_YA_VIZURI_N.VIELEZI', 'Uses the manner word for a quality of a thing (Chakula ni vizuri for Chakula ni kizuri).', '{"question":"Ni lipi sahihi?","wrong_answer":"Dawa hii ni vizuri.","correct_answer":"Dawa hii ni nzuri."}'::jsonb, 'Vizuri is heard everywhere ("ni vizuri") and the child uses it for things too.', 'The question "Ni lipi sahihi?" with "Dawa hii ni vizuri." among the options.', 'Sort sentences: how something is done (vizuri) and what a thing is like (kizuri, mzuri, nzuri).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI.M2_SAU_NEAR_T10', 'KISW.G2.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'Says /l/ for /r/, so "radi" becomes "ladi".', '{"question":"Mwalimu anasema \"radi\". Neno lipi limetamkwa vizuri?","wrong_answer":"ladi","correct_answer":"radi"}'::jsonb, 'Many Kenyan first languages have no /r/, or do not separate it from /l/; the child puts in the home sound.', 'The question "Mwalimu anasema "radi". Neno lipi limetamkwa vizuri?" with "ladi" among the options.', 'Say the two side by side, slowly, watching the mouth; the child holds up a card for the sound he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI.M2_SAU_NEAR2_T10', 'KISW.G2.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'Says /r/ for /l/, so "leo" becomes "reo".', '{"question":"Neno lipi limetamkwa vizuri?","wrong_answer":"reo","correct_answer":"leo"}'::jsonb, '/l/ and /r/ are close; a first language with only one of them puts that one in both places.', 'The question "Neno lipi limetamkwa vizuri?" with "reo" among the options.', 'Contrast the two with a mirror and a hand before the mouth; the child says which he hears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI.M2_SAU_SYLL_T10', 'KISW.G2.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'Splits "radi" by letters rather than by syllables (each Kiswahili syllable ends in a vowel).', '{"question":"Neno \"radi\" lina silabi zipi?","wrong_answer":"r-a-d-i","correct_answer":"ra-di"}'::jsonb, 'The child has learnt letters one by one and has not been shown that a syllable is a sound that ends in a vowel.', 'The question "Neno "radi" lina silabi zipi?" with "r-a-d-i" among the options.', 'Clap the word: one clap per vowel; the consonants go with the vowel after them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI.M2_SAU_PICK_T10', 'KISW.G2.KUSIKI.T10_MATAMSHI_BORA.MATAMSHI', 'Picks a word with no target sound when asked for one that has it.', '{"question":"Ni neno lipi lina sauti /r/, /l/?","wrong_answer":"jua","correct_answer":"baridi"}'::jsonb, 'The child looks at the first letter or the picture, not at the sound.', 'The question "Ni neno lipi lina sauti /r/, /l/?" with "jua" among the options.', 'Underline the target sound in each word on the card before choosing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_SOUND_T10', 'KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads the target word wrongly: "radi" as "ladi".', '{"question":"Neno \"radi\" linasomwa vipi?","wrong_answer":"ladi","correct_answer":"radi"}'::jsonb, 'The child reads the letters with the sounds of his first language, or adds a vowel to break the cluster.', 'The question "Neno "radi" linasomwa vipi?" with "ladi" among the options.', 'Pick out the target words before reading; practise them on cards, then read the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_WORD_T10', 'KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Mvua kubwa ilinyesha jana usiku.\"?","wrong_answer":"Mvua ... kubwa ... ilinyesha ... jana ... usiku.","correct_answer":"Mvua kubwa ilinyesha jana usiku."}'::jsonb, 'The child is still decoding each word; he has not yet read a group of words as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Mvua kubwa ilinyesha jana usiku."?" with "Mvua ... kubwa ... ilinyesha ... jana ... usiku." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it in one breath.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_QUIET_T10', 'KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads so softly (or so loudly, shouting) that the class cannot follow.', '{"question":"Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?","wrong_answer":"ya chini ili nisikosee mbele ya wenzangu","correct_answer":"ya kusikika na wote darasani, bila kupiga kelele"}'::jsonb, 'Shyness, or the belief that reading well means reading loud.', 'The question "Unaposoma mbele ya darasa, sauti yako inafaa kuwa vipi?" with "ya chini ili nisikosee mbele ya wenzangu" among the options.', 'Stand the reader at the front and a listener at the back: the listener raises a hand when he hears every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_PACE_T10', 'KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Kasi ifaayo ya kusoma kifungu ni ipi?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, karibu maneno 45 kwa dakika"}'::jsonb, 'Reading races in class reward speed; nobody asked whether the listeners understood.', 'The question "Kasi ifaayo ya kusoma kifungu ni ipi?" with "haraka iwezekanavyo" among the options.', 'Time two readings, one very fast and one at speaking pace; the listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M2_UFS_MARK_T10', 'KISW.G2.KUSOMA.T10_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question in the flat voice of a statement and runs on through the koma and kikomo.', '{"question":"Sentensi \"Je, leo kuna jua?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the marks.', 'The question "Sentensi "Je, leo kuna jua?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that fits each reading; clap at each kikomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI.TAHAJIA.M2_TAH_MT_T10', 'KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI.TAHAJIA', 'Spells the word with the sound of his first language: "radi" written "ladi".', '{"question":"Ni tahajia ipi sahihi?","wrong_answer":"ladi","correct_answer":"radi"}'::jsonb, 'The child writes as he says the word; if his first language merges the two sounds, the letter is a guess.', 'The question "Ni tahajia ipi sahihi?" with "ladi" among the options.', 'Keep a list of the class''s hard pairs (l/r, s/sh, z/dh, s/th); say each word slowly before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI.TAHAJIA.M2_TAH_NASAL_T10', 'KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI.TAHAJIA', 'Drops the nasal: "mvua" written "vua".', '{"question":"Ni tahajia ipi sahihi?","wrong_answer":"vua","correct_answer":"mvua"}'::jsonb, 'The n or m before a consonant is soft and quick; the child does not hear it.', 'The question "Ni tahajia ipi sahihi?" with "vua" among the options.', 'Hum the nasal before the word (mmm-bwa, nnn-dege).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI.TAHAJIA.M2_TAH_VOWEL_T10', 'KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI.TAHAJIA', 'Writes a long vowel short, so the word changes: "saa" written "sa".', '{"question":"Andika neno lenye maana ya \"kifaa cha kuonyesha wakati\".","wrong_answer":"sa","correct_answer":"saa"}'::jsonb, 'The child hears the length but does not know it is shown by two letters.', 'The question "Andika neno lenye maana ya "kifaa cha kuonyesha wakati"." with "sa" among the options.', 'Clap the two vowels as two beats; compare a word with one and two vowels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI.TAHAJIA.M2_TAH_NGAPOS_T10', 'KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI.TAHAJIA', 'Writes ng'' without the apostrophe (ngombe for ng''ombe), or puts it where it does not belong (ng''oma for ngoma).', '{"question":"Ni tahajia ipi sahihi ya mnyama anayetupa maziwa?","wrong_answer":"ngombe","correct_answer":"ng''ombe"}'::jsonb, 'Ng'' and ng are two sounds; the apostrophe looks like dirt on the page to the child.', 'The question "Ni tahajia ipi sahihi ya mnyama anayetupa maziwa?" with "ngombe" among the options.', 'Say ng''ombe and ngoma: the first has no g sound; mark it with the apostrophe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI.TAHAJIA.M2_TAH_JOIN_T10', 'KISW.G2.KUANDI.T10_MANENO_NA_SENTENSI.TAHAJIA', 'Joins two words into one, or splits one word into two (kwasababu; mwana funzi).', '{"question":"Ni lipi sahihi?","wrong_answer":"Nilichelewa kwasababu ya mvua.","correct_answer":"Nilichelewa kwa sababu ya mvua."}'::jsonb, 'In speech the words run together; the child has not seen each written apart.', 'The question "Ni lipi sahihi?" with "Nilichelewa kwasababu ya mvua." among the options.', 'Count the words aloud with a finger for each before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME.M2_SAR_NEGATE_T10', 'KISW.G2.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'Gives the negative of the verb (hafungui) instead of its opposite action (funga).', '{"question":"Kinyume cha \"fungua\" (dirisha) ni?","wrong_answer":"usifungue","correct_answer":"funga"}'::jsonb, 'The child thinks "opposite" means "not doing it".', 'The question "Kinyume cha "fungua" (dirisha) ni?" with "usifungue" among the options.', 'Act it: fungua the door, then funga it; not doing anything is not the opposite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME.M2_SAR_ADDUA_T10', 'KISW.G2.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'Makes an opposite by adding -ua to any verb (keti -> ketua).', '{"question":"Kinyume cha \"simama\" ni?","wrong_answer":"simamua","correct_answer":"keti"}'::jsonb, 'Fungua/funga and vaa/vua show a pattern, and the child uses it everywhere.', 'The question "Kinyume cha "simama" ni?" with "simamua" among the options.', 'Sort pairs into two piles: made with -ua (funga-fungua) and different words (keti-simama).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME.M2_SAR_SAME_T10', 'KISW.G2.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'Gives a word of the same meaning as the opposite (simama - inuka).', '{"question":"Kinyume cha \"anza\" ni?","wrong_answer":"zindua","correct_answer":"maliza"}'::jsonb, 'The child knows the words go together but not that they mean the same.', 'The question "Kinyume cha "anza" ni?" with "zindua" among the options.', 'Act both words: if the action is the same, it is not the opposite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G2.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME.M2_SAR_NOUNOPP_T10', 'KISW.G2.SARUFI.T10_VINYUME_VYA_VITENDO.VINYUME', 'Gives a place or thing word as the opposite of an action (ingia - nje).', '{"question":"Kinyume cha \"panda\" (mlima) ni?","wrong_answer":"chini","correct_answer":"shuka"}'::jsonb, 'Ingia and nje are heard together in "ingia ndani, toka nje".', 'The question "Kinyume cha "panda" (mlima) ni?" with "chini" among the options.', 'Ask "Ni kitendo?" before accepting: the opposite of an action is an action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
